async function requestCode(){
  const email=(document.getElementById("loginEmail").value||"").trim();
  const msg=document.getElementById("loginMsg");
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ msg.style.color="var(--k-dc2626)"; msg.textContent="Bitte oben eine gültige E-Mail eingeben."; return; }
  msg.style.color="var(--k-374151)"; msg.textContent="⏳ Prüfe E-Mail…";
  let exists=false; try{ const r=await client.rpc("cb_email_exists",{p_email:email}); exists=!!r.data; }catch(e){}
  msg.textContent = exists?"⏳ Sende Code…":"⏳ Neues Konto – sende Code…";
  const {error}=await client.auth.signInWithOtp({ email, options:{ shouldCreateUser: !exists } });
  if(error){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+error.message; return; }
  document.getElementById("codeBox").style.display="block";
  const ci=document.getElementById("loginCode"); if(ci) setTimeout(()=>ci.focus(),60);
  msg.style.color="var(--k-16a34a)";
  msg.innerHTML = (exists?"✅ Code an <b>":"🆕 Neues Konto – Code an <b>")+esc(email)+"</b> gesendet. Bitte den 6-stelligen Code aus der E-Mail eingeben.";
}
async function verifyCode(){
  const email=(document.getElementById("loginEmail").value||"").trim();
  const token=(document.getElementById("loginCode").value||"").trim().replace(/\s/g,"");
  const msg=document.getElementById("loginMsg");
  if(!email||!token){ msg.style.color="var(--k-dc2626)"; msg.textContent="E-Mail und Code eingeben."; return; }
  msg.style.color="var(--k-374151)"; msg.textContent="⏳ Prüfe Code…";
  const {error}=await client.auth.verifyOtp({ email, token, type:"email" });
  if(error){ msg.style.color="var(--k-dc2626)"; msg.textContent="Code ungültig oder abgelaufen: "+error.message; return; }
  document.getElementById("loginCode").value="";
  msg.style.color="var(--k-16a34a)"; msg.textContent="✓ angemeldet"; closeLogin();
}
