/* ===========================================================================
   PREMIUM-BANDEROLE IN DER KOPFLEISTE (Ralph 01.08.2026)
   ---------------------------------------------------------------------------
   Sie saß bisher im Dashboard-Kasten und war damit nur auf der Startseite zu
   sehen. Jetzt sitzt sie in der Kopfleiste (.hero) - also auf JEDER Seite.

   Warum hier und nicht im Dashboard eingehängt: der Status hängt an ME, und ME
   ändert sich beim An- und Abmelden. updateAuthUI läuft genau dann - eine
   Stelle, ein Zeitpunkt. Würde sie beim Rendern des Dashboards gebaut, zeigte
   sie nach dem Abmelden noch den alten Stand, bis jemand die Seite wechselt.

   .hero hat position:sticky - das ist ein Positionierungskontext, das absolut
   gesetzte Band bleibt also in der Leiste. overflow:hidden ist PFLICHT, sonst
   ragt die gedrehte Fläche über den Rand hinaus.
   =========================================================================== */
function riBanderoleStatus(){
  if(!ME) return {text:'', art:''};
  var tb = ME.trial_bis ? new Date(ME.trial_bis) : null;
  var isTrial = (ME.sub_status==='trialing') && tb && tb > new Date();
  if(isTrial){
    var d = Math.max(0, Math.ceil((tb - new Date())/86400000));
    return {text: d+' Tag'+(d===1?'':'e')+' Test', art:'trial'};
  }
  if(ME.is_premium) return {text:'PREMIUM', art:'premium'};
  return {text:'', art:''};
}
function riBanderoleKopf(){
  var hero = document.querySelector('.hero');
  if(!hero) return;
  var alt = document.getElementById('riBandKopf');
  var s = riBanderoleStatus();
  if(!s.text){ if(alt) alt.remove(); return; }   /* ohne Status kein Band */
  if(!alt){
    alt = document.createElement('div');
    alt.id = 'riBandKopf';
    /* Das Band darf nichts anklickbar machen, was darunter liegt */
    alt.style.cssText = 'position:absolute;top:0;right:0;width:118px;height:118px;'
      + 'overflow:hidden;pointer-events:none;z-index:5';
    if(getComputedStyle(hero).position === 'static') hero.style.position = 'relative';
    hero.style.overflow = 'hidden';
    hero.appendChild(alt);
  }
  var bg = (s.art==='premium') ? 'var(--green)'     : 'var(--greenlt)';
  var fg = (s.art==='premium') ? 'var(--auf-gruen)' : 'var(--greendk)';
  alt.innerHTML = '<div style="position:absolute;transform:rotate(45deg);background:'+bg
    + ';color:'+fg+';font-size:10px;font-weight:800;letter-spacing:.06em;text-align:center;'
    + 'width:170px;top:22px;right:-48px;padding:4px 0;'
    + 'box-shadow:0 2px 6px rgba(20,40,70,.18)">'+esc(s.text)+'</div>';
}
if(typeof window!=='undefined'){ window.riBanderoleKopf=riBanderoleKopf; }
function updateGate(){
  const form=document.getElementById("vorForm"), gate=document.getElementById("vorGate");
  if(!form||!gate) return;
  if(ME&&hasFeat('erfassung')){ form.style.display=""; gate.style.display="none"; }
  else { form.style.display="none"; gate.style.display=""; gate.innerHTML=gateHtml('erfassung'); }
}
/* 🔴 16.09.2026, GEMESSEN an einem Seitenaufruf von admin.html (Supabase
   edge_logs, 04:41): applyAuthState lief DREIMAL. Supabase meldet beim Start
   mehrere Auth-Ereignisse (INITIAL_SESSION, SIGNED_IN, TOKEN_REFRESHED), und
   daneben fragt die Seite die Sitzung noch selbst ab. Jeder dieser Laeufe holte
   die Verknuepfung, den Benutzersatz, die Stufenrechte und alles, was an den
   sichtbaren Ansichten haengt - dreimal dieselbe Antwort.
   Der Riegel vergleicht die BENUTZER-KENNUNG der Sitzung. Ist sie dieselbe wie
   beim letzten Lauf, gibt es nichts Neues zu holen und der Lauf entfaellt.
   Aendert sich etwas - Anmeldung, Abmeldung, anderer Benutzer -, laeuft er wie
   bisher.
   🔴 Die Unterschrift bleibt applyAuthState(session), einteilig. Ein zweiter
   Parameter "erzwingen" war gebaut und ist wieder RAUS: niemand rief ihn, und
   der Riegel in bereiche/test-wasser-ladeweg.js prueft diese Unterschrift
   wortgenau. Ein ungenutzter Schalter waere hier beides gewesen - toter Code
   und ein roter Test. Wer nach einer Profil-Aenderung neu laden will, ruft
   refreshMe(); das tut der Profilweg auch heute schon. */
var _authStand = null;   /* null = noch nie gelaufen; '' = abgemeldet */
async function applyAuthState(session){
  var kennung = (session && session.user && session.user.id) ? String(session.user.id) : '';
  if(_authStand !== null && _authStand === kennung) return;
  _authStand = kennung;
  if(session){ await refreshMe(); } else { ME=null; TB_USER="U001"; await refreshMyFeatures(); }
  updateAuthUI(); updateGate();
  const vis=id=>{ const e=document.getElementById(id); return e && e.style.display!=="none"; };
  REZEPTE=null; if(vis("rezeptView")) loadRezepte();
  if(vis("tagebuchView")) loadTagebuch();
  if(vis("profilView")) loadProfil();
  if(vis("stufenView")) loadStufen();
  if(vis("usersView")) loadUsers();
  if(vis("startView")) renderStart();
  if(typeof applyAdminMode==='function') applyAdminMode();
}
// WICHTIG: im onAuthStateChange-Callback KEINE weiteren Supabase-Aufrufe direkt awaiten
// (blockiert die Auth-Verwaltung). Daher per setTimeout aus dem Callback herauslösen.
client.auth.onAuthStateChange((_e,session)=>{ setTimeout(()=>{ applyAuthState(session); },0); });
(async ()=>{ try{ const {data:{session}}=await client.auth.getSession(); applyAuthState(session); }catch(e){ updateAuthUI(); updateGate(); } })();

/* ---- Mein Profil ---- */
function _selVal(id,val){ const el=document.getElementById(id); if(!el) return;
  if(val==null){ el.value=""; return; }
  if(el.tagName==="SELECT" && ![...el.options].some(o=>o.value==String(val))){ const o=document.createElement("option"); o.value=val; o.textContent=val; el.appendChild(o); }
  el.value=val; }
function _numOrNull(id){ const v=parseFloat((document.getElementById(id).value||"").replace(",",".")); return isNaN(v)?null:v; }
async function loadProfil(){
  const gate=document.getElementById("profilGate"), inner=document.getElementById("profilInner");
  if(!ME || !hasFeat('profil')){ if(inner)inner.style.display="none"; if(gate){ gate.style.display=""; gate.innerHTML=gateHtml('profil'); } return; }
  if(gate)gate.style.display="none"; if(inner)inner.style.display="";
  const {data}=await client.rpc("cb_profil"); const b=(data&&data[0])||{};
  { const e=document.getElementById("pfEmail"); if(e) e.textContent=b.Email||"–"; }
  { const n=document.getElementById("pfName"); if(n) n.value=b.Name||(ME&&ME.name)||""; }
  _selVal("pfGeb",b.Geburtsdatum);
  { const c=document.getElementById("pfNews"); if(c) c.checked=!!b.Newsletter; }
  _selVal("pfAlter",b.Alter); _selVal("pfGeschlecht",b.Geschlecht); _selVal("pfGroesse",b.Groesse_cm);
  pfAgeFromGeb();
  _selVal("pfGewicht",b.Gewicht_kg); _selVal("pfAktiv",b.Aktivitaetslevel); _selVal("pfErn",b.Ernaehrungsform);
  /* W8 Baustein 2 (12.08.2026): Diabetestyp vorbesetzen. cb_profil liefert SETOF "Benutzer",
     die Spalte kommt also ohne zweiten Leseweg mit (§22 - kein neuer Ladeweg noetig).
     NULL wird zu "" und trifft damit die Option "Keine Angabe". */
  _selVal("pfDiab", b.Diabetes_Typ);
  /* 25.09.2026 (Ralph: "ja, du kannst beides bauen"): Schwangerschaft/Stillzeit.
     Bestimmt zusammen mit Geschlecht und Alter die Naehrstoff-Sollwerte
     (D-A-CH/DGE). Das Feld steht in index.html - die darf ich nicht anfassen;
     bis Ralph den Schnipsel einsetzt, greift hier schlicht nichts (§1.7: kein
     stiller Pfad, aber auch kein Fehler wegen eines Feldes, das es noch nicht
     gibt). Nur fuer weiblich sichtbar - pfZustandToggle. */
  _selVal("pfZustand", b.Zustand);
  pfZustandToggle();
  _selVal("pfKcal",b.Kalorienziel_kcal); _selVal("pfEiw",b.Eiweiss_ziel_g); _selVal("pfKh",b.KH_ziel_g); _selVal("pfFett",b.Fett_ziel_g);
  _selVal("pfAnFr",b.Anteil_Fr); _selVal("pfAnMi",b.Anteil_Mi); _selVal("pfAnAb",b.Anteil_Ab); _selVal("pfAnSn",b.Anteil_Sn);
  renderTrainTage(b.Trainingstage, b.Trainingstag_Plus);
  loadZielHistorie();
  renderProfilMass();
  try{ pushBoxRender(); }catch(e){}   /* 28z24 */
  try{ hhProfilRender(); }catch(e){}   /* 28z29 */
  try{ blProfilRender(); }catch(e){}   /* Etappe 2: Bundesland (freiwillig) */
  try{ zeitenRender(); }catch(e){}     /* Work #770: Zeiten im Tagesablauf */
  loadZyklus();
  pfTab('daten');
}
async function saveAnteile(){
  const msg=document.getElementById("pfAnMsg");
  const n=id=>{const v=parseInt((document.getElementById(id)||{}).value,10); return isNaN(v)?null:v;};
  const fr=n("pfAnFr"), mi=n("pfAnMi"), ab=n("pfAnAb"), sn=n("pfAnSn");
  const sum=(fr||0)+(mi||0)+(ab||0)+(sn||0);
  if(sum===0){ msg.style.color="var(--k-dc2626)"; msg.textContent="Bitte Prozente eingeben (Summe ~100)."; return; }
  if(Math.abs(sum-100)>1){ msg.style.color="var(--k-b45309)"; msg.textContent="Hinweis: Summe ist "+sum+" % (ideal 100). Wird trotzdem anteilig genutzt."; }
  const {error}=await client.rpc("cb_anteile_setzen",{p_fr:fr,p_mi:mi,p_ab:ab,p_sn:sn});
  if(error){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+error.message; return; }
  if(Math.abs(sum-100)<=1){ msg.style.color="var(--k-16a34a)"; msg.textContent="✓ gespeichert"; }
}
async function loadZielHistorie(){
  const box=document.getElementById("zielHistBox"); if(!box) return;
  const {data,error}=await client.rpc("cb_ziel_historie");
  if(error){ box.innerHTML=""; return; }
  const rows=data||[];
  if(!rows.length){ box.innerHTML='<div style="font-size:12px;color:var(--k-9aa7a0)">Noch kein Ziel-Verlauf – beim nächsten Speichern wird ein Eintrag angelegt.</div>'; return; }
  let h='<div style="font-size:12px;font-weight:600;color:var(--green);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">Ziel-Verlauf</div>';
  h+='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px">';
  h+='<tr style="color:var(--muted)"><th style="text-align:left;padding:4px 8px">ab</th><th style="text-align:right;padding:4px 8px">kcal</th><th style="text-align:right;padding:4px 8px">Eiweiß</th><th style="text-align:right;padding:4px 8px">KH</th><th style="text-align:right;padding:4px 8px">Fett</th></tr>';
  rows.forEach((r,i)=>{ const cur=i===0?' style="font-weight:700"':'';
    h+='<tr style="border-top:1px solid var(--line)"><td'+cur+' style="padding:5px 8px">'+esc(r.gueltig_ab)+(i===0?' <span style="color:var(--green);font-weight:600">aktuell</span>':'')+'</td>'
      +'<td style="text-align:right;padding:5px 8px">'+(r.kcal??'–')+'</td>'
      +'<td style="text-align:right;padding:5px 8px">'+(r.eiweiss??'–')+'</td>'
      +'<td style="text-align:right;padding:5px 8px">'+(r.kh??'–')+'</td>'
      +'<td style="text-align:right;padding:5px 8px">'+(r.fett??'–')+'</td></tr>';
  });
  h+='</table></div>';
  box.innerHTML=h;
}
async function saveProfil(){
  const msg=document.getElementById("pfMsg");
  { const nm=(document.getElementById("pfName")||{}).value; if(nm!=null){ try{ await client.rpc("cb_name_speichern",{p_name:nm}); if(ME&&nm.trim()) ME.name=nm.trim(); }catch(e){} } }
  const {error}=await client.rpc("cb_profil_speichern",{
    p_alter:_numOrNull("pfAlter"), p_gewicht:_numOrNull("pfGewicht"), p_groesse:_numOrNull("pfGroesse"),
    p_geschlecht:document.getElementById("pfGeschlecht").value||null,
    p_aktivitaet:document.getElementById("pfAktiv").value||null,
    p_ernaehrungsform:document.getElementById("pfErn").value||null });
  if(error){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+error.message; return; }
  const geb=(document.getElementById("pfGeb")||{}).value||null;
  const news=!!(document.getElementById("pfNews")||{}).checked;
  const {error:e2}=await client.rpc("cb_profil_extra",{p_geburtsdatum:geb,p_newsletter:news});
  if(e2){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+e2.message; return; }
  /* W8 Baustein 2 (12.08.2026): Diabetestyp ueber den EIGENEN Schreibweg cb_profil_diabetes -
     eine Gesundheitsangabe gehoert nicht in denselben Aufruf wie Groesse und Gewicht.
     Leere Auswahl geht als NULL raus, nicht als Leerstring - sonst schlaegt der CHECK auf
     Benutzer.Diabetes_Typ zu (§3.4: leer heisst "keine Angabe", nicht "sonstiger").
     Fehler wird BENANNT, nicht verschluckt (§1.7, §11.4). */
  /* Schwangerschaft/Stillzeit ueber den EIGENEN Schreibweg - wie beim
     Diabetestyp gehoert eine solche Angabe nicht in denselben Aufruf wie
     Groesse und Gewicht. Wer nicht weiblich ist, schickt NULL: die Angabe
     wuerde sonst nach einem Wechsel still weiterwirken. */
  const _zEl=document.getElementById("pfZustand");
  if(_zEl){
    const g=(document.getElementById("pfGeschlecht")||{}).value||"";
    const z=(g==="weiblich" && (_zEl.value||"").trim()) ? _zEl.value.trim() : null;
    const {error:eZ}=await client.rpc("cb_profil_zustand",{p_zustand:z});
    if(eZ){ msg.style.color="var(--k-dc2626)"; msg.textContent="Profil gespeichert – Schwangerschaft/Stillzeit nicht: "+eZ.message; loadProfil(); return; }
  }
  const _dEl=document.getElementById("pfDiab");
  if(_dEl){
    const dia=(_dEl.value||"").trim()||null;
    const {error:e3}=await client.rpc("cb_profil_diabetes",{p_diabetes_typ:dia});
    if(e3){ msg.style.color="var(--k-dc2626)"; msg.textContent="Profil gespeichert – Diabetes-Angabe nicht: "+e3.message; loadProfil(); return; }
  }
  const ttOk = await saveTrainTage();
  if(!ttOk){ msg.style.color="var(--k-e8920c)"; msg.textContent="Profil gespeichert – Trainingstage nicht. Bitte nochmal."; loadProfil(); return; }
  msg.style.color="var(--k-16a34a)"; msg.textContent="✓ gespeichert"; loadProfil(); refreshMe();
}
/* ---- Zyklus (EN-12) ---- */
function pfZyklusToggle(){
  /* haengt am onchange von pfGeschlecht in index.html - die darf ich nicht
     anfassen, also zieht der Zustand hier mit, statt einen zweiten Handler
     zu verlangen. */
  try{ pfZustandToggle(); }catch(e){}
  const box=document.getElementById("pfZyklusBox"); if(!box) return;
  const g=(document.getElementById("pfGeschlecht")||{}).value||"";
  box.style.display = (g==="weiblich") ? "" : "none";
}
/* Eine Frage nach Schwangerschaft im Profil eines Mannes waere Unfug -
   deshalb dieselbe Regel wie beim Zyklus. */
function pfZustandToggle(){
  const el=document.getElementById("pfZustand"); if(!el) return;
  const lbl=document.getElementById("pfZustandLbl")||el.closest("label")||el;
  const g=(document.getElementById("pfGeschlecht")||{}).value||"";
  lbl.style.display = (g==="weiblich") ? "" : "none";
}
async function loadZyklus(){
  pfZyklusToggle();
  try{
    const {data}=await client.rpc("cb_zyklus_get");
    const r=(data&&data[0])||{};
    window._zyklus = (r.start) ? {start:r.start, laenge:r.laenge||28, ende:r.ende||null} : {};
    _selVal("pfZykStart", r.start||"");
    _selVal("pfZykEnde", r.ende||"");
    _selVal("pfZykLen", r.laenge||28);
    var sv=document.getElementById("pfZykStkVal"); if(sv) sv.value=r.blutung||"";
    var wv=document.getElementById("pfZykWohlVal"); if(wv) wv.value=(r.wohl!=null?String(r.wohl):"");
    zykCalInit();
    zykUpdateLabels();
  }catch(e){ window._zyklus={}; }
}
async function saveZyklus(){
  const msg=document.getElementById("pfZykMsg");
  const s=(document.getElementById("pfZykStart")||{}).value||null;
  const e=(document.getElementById("pfZykEnde")||{}).value||null;
  const l=parseInt((document.getElementById("pfZykLen")||{}).value,10)||28;
  const stk=(document.getElementById("pfZykStkVal")||{}).value||null;
  const wohl=parseInt((document.getElementById("pfZykWohlVal")||{}).value,10)||null;
  if(!s){ if(msg){ msg.style.color="var(--k-dc2626)"; msg.textContent="Bitte im Kalender einen Zyklusbeginn antippen."; } return; }
  if(e && e<s){ if(msg){ msg.style.color="var(--k-dc2626)"; msg.textContent="Periodenende darf nicht vor dem Beginn liegen."; } return; }
  const {error}=await client.rpc("cb_zyklus_speichern",{p_start:s,p_laenge:l,p_ende:e,p_blutung:stk,p_wohl:wohl});
  if(error){ if(msg){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+error.message; } return; }
  window._zyklus={start:s, laenge:Math.min(45,Math.max(20,l)), ende:e};
  if(msg){ msg.style.color="var(--k-16a34a)"; msg.textContent="✓ gespeichert – Hinweise erscheinen im Tagebuch."; }
  zyklusPhaseText();
  if(document.getElementById("tbZyklus")) renderZyklusHint();
}
/* Zyklus-Kalender als Bereichswähler: 1. Klick = Start, 2. Klick = Ende */
function zykCalInit(){
  var box=document.getElementById('pfZykCal'); if(!box) return;
  var s=(document.getElementById('pfZykStart')||{}).value||'';
  var e=(document.getElementById('pfZykEnde')||{}).value||'';
  var base=s?new Date(s+'T00:00:00'):new Date();
  window._zykCal={y:base.getFullYear(), m:base.getMonth(), start:s||null, end:e||null, phase:(s&&!e)?'end':'start'};
  zykCalRender();
}
function zykUpdateLabels(){
  var s=(document.getElementById('pfZykStart')||{}).value||'';
  var e=(document.getElementById('pfZykEnde')||{}).value||'';
  var fmt=function(ds){ if(!ds) return '–'; return new Date(ds+'T00:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}); };
  var sl=document.getElementById('pfZykStartLbl'); if(sl) sl.textContent=fmt(s);
  var el=document.getElementById('pfZykEndeLbl'); if(el) el.textContent=fmt(e);
  var dl=document.getElementById('pfZykDauerLbl');
  if(dl){ if(s&&e){ var dd=Math.round((new Date(e+'T00:00:00')-new Date(s+'T00:00:00'))/86400000)+1; dl.textContent=(dd>=1?dd+' Tag'+(dd===1?'':'e'):'–'); } else { dl.textContent='–'; } }
  window._zyklus=window._zyklus||{}; if(s){ window._zyklus.start=s; window._zyklus.ende=e||null; if(!window._zyklus.laenge) window._zyklus.laenge=28; }
  zyklusPhaseText();
}
function zykCalNav(n){ var st=window._zykCal; if(!st) return; st.m+=n; if(st.m<0){st.m=11;st.y--;} if(st.m>11){st.m=0;st.y++;} zykCalRender(); }
function zykCalPick(ds){
  var st=window._zykCal; if(!st) return;
  if(st.phase==='start' || (st.start&&st.end)){ st.start=ds; st.end=null; st.phase='end'; }
  else { if(ds<st.start){ st.start=ds; st.phase='end'; } else { st.end=ds; st.phase='start'; } }
  var si=document.getElementById('pfZykStart'); if(si) si.value=st.start||'';
  var ei=document.getElementById('pfZykEnde'); if(ei) ei.value=st.end||'';
  zykCalRender();
  if(typeof zykUpdateLabels==='function') zykUpdateLabels();
}
function zykCalRender(){
  var box=document.getElementById('pfZykCal'); if(!box) return;
  var st=window._zykCal; if(!st) return;
  var first=new Date(st.y, st.m, 1);
  var startWd=(first.getDay()+6)%7;
  var daysInM=new Date(st.y, st.m+1, 0).getDate();
  var mName=first.toLocaleDateString('de-DE',{month:'long',year:'numeric'});
  var wd=['M','D','M','D','F','S','S'], today=tbToday();
  var html='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">'
    +'<button type="button" onclick="zykCalNav(-1)" style="border:0;background:none;cursor:pointer;font-size:16px;padding:2px 8px">‹</button>'
    +'<span style="font-weight:700;font-size:13.5px">'+mName+'</span>'
    +'<button type="button" onclick="zykCalNav(1)" style="border:0;background:none;cursor:pointer;font-size:16px;padding:2px 8px">›</button></div>';
  html+='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center;font-size:10px;color:var(--muted);margin-bottom:2px">'+wd.map(function(w){return '<div>'+w+'</div>';}).join('')+'</div>';
  html+='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px">';
  var i; for(i=0;i<startWd;i++) html+='<div></div>';
  var d; for(d=1; d<=daysInM; d++){
    var ds=st.y+'-'+String(st.m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    var isStart=st.start===ds, isEnd=st.end===ds;
    var inRange=st.start&&st.end&&ds>st.start&&ds<st.end;
    var future=ds>today;
    var bg=(isStart||isEnd)?'var(--k-db2777)':(inRange?'var(--k-fbcfe8)':'transparent');
    var col=(isStart||isEnd)?'var(--k-ffffff)':(future?'var(--k-c9c4bd)':'var(--ink)');
    html+='<button type="button" '+(future?'disabled':'onclick="zykCalPick(\''+ds+'\')"')+' style="aspect-ratio:1;border:0;border-radius:8px;background:'+bg+';color:'+col+';cursor:'+(future?'default':'pointer')+';font-size:12.5px">'+d+'</button>';
  }
  html+='</div>';
  var hint = (st.phase==='end') ? 'Jetzt <b>Periodenende</b> wählen (oder denselben Tag).' : 'Nächster Klick = <b>Zyklusbeginn</b>, dann das <b>Ende</b>.';
  html+='<div style="font-size:11px;color:var(--muted);margin-top:6px">'+hint+' Danach <b>Speichern</b>.</div>';
  box.innerHTML=html;
}
// Zyklustag & Phase; nutzt tbToday() als Bezugstag
function zyklusInfo(){
  const z=window._zyklus; if(!z||!z.start) return null;
  const start=new Date(z.start+"T00:00:00");
  const ref=(typeof tbToday==="function")? new Date(tbToday()+"T00:00:00") : new Date();
  const diff=Math.floor((ref-start)/86400000);
  if(isNaN(diff)||diff<0) return null;
  const len=z.laenge||28;
  const day=(diff%len)+1;
  const zyklen=Math.floor(diff/len);
  const nextStart=new Date(start.getTime()+(zyklen+1)*len*86400000);
  const bis=Math.round((nextStart-ref)/86400000);
  let mensDays=5;
  if(z.ende){ var _ed=Math.floor((new Date(z.ende+"T00:00:00")-start)/86400000)+1; if(!isNaN(_ed)&&_ed>=1) mensDays=Math.min(14,_ed); }
  let phase="Follikelphase", hint=null;
  if(day<=mensDays){
    phase="Menstruation";
    hint={emoji:"🩸", title:"Menstruation · Tag "+day+" von "+mensDays,
      text:"Durch den Blutverlust ist der <b>Eisenbedarf</b> oft erhöht. Eisenreiche Lebensmittel (Hülsenfrüchte, Haferflocken, grünes Gemüse, rotes Fleisch) mit etwas Vitamin C (Paprika, Zitrus) kombinieren – das verbessert die Eisenaufnahme (zugelassene EU-Angabe). <b>Eisen</b> trägt zur Verringerung von Müdigkeit und Ermüdung bei."};
  } else if(bis<=5){
    phase="Lutealphase";
    hint={emoji:"🌙", title:"Kurz vor der Periode · noch ~"+bis+" Tage",
      text:"In dieser Phase sind mehr Hunger und <b>Heißhunger auf Süßes</b> sowie ein leicht höherer Energie- und <b>Magnesium</b>bedarf verbreitet. Vollkorn, Obst, Nüsse und dunkle Schokolade in Maßen können helfen."};
  }
  return {day, len, bis, phase, hint, nextStart};
}
function zyklusPhaseText(){
  const el=document.getElementById("pfZykPhase"); if(!el) return;
  const z=zyklusInfo();
  if(!z){ el.textContent=""; return; }
  var fmt=function(d){ return d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'}); };
  var ov=new Date(z.nextStart.getTime()-14*86400000);
  var fs=new Date(ov.getTime()-5*86400000);
  el.innerHTML="Heute: <b>Zyklustag "+z.day+"</b> · "+esc(z.phase)+" · nächste Periode in ~"+z.bis+" Tagen."
    +"<br>🌱 Fruchtbare Phase (Schätzung): <b>"+fmt(fs)+"–"+fmt(ov)+"</b> · Eisprung ~"+fmt(ov)+"."
    +"<br><span style=\"color:var(--k-9aa7a0)\">Schätzung bei ~"+z.len+"-Tage-Zyklus. Keine Verhütungs- oder medizinische Beratung.</span>";
}
function renderZyklusHint(){
  const el=document.getElementById("tbZyklus"); if(!el) return;
  const z=zyklusInfo();
  if(!z||!z.hint){ el.innerHTML=""; return; }
  el.innerHTML='<div style="background:var(--tb-card);border:1px solid var(--k-7a3b5a);border-radius:12px;padding:12px 14px;margin-bottom:12px">'
    +'<div style="font-weight:600;font-size:13.5px;margin-bottom:3px">'+z.hint.emoji+' '+esc(z.hint.title)+'</div>'
    +'<div style="font-size:12.5px;color:var(--tb-muted);line-height:1.55">'+z.hint.text+'</div>'
    +'<div style="font-size:11px;color:var(--tb-muted);opacity:.75;margin-top:6px">Allgemeine Info, keine medizinische Beratung.</div></div>';
}
