  studien_hinweise:{t:"Studien-Hinweise",bg:"var(--k-fff7e6)",fg:"var(--k-92400e)"},
  labor:{t:"nur Labor",bg:"var(--k-f2f5f3)",fg:"var(--k-5a6660)"},
