  if(d && d._zusatz_v2_fehler)
    return kopf+'<div style="font-size:13px;color:var(--k-b91c1c);background:var(--k-fde8e8);border-radius:9px;padding:9px 11px">Zusatzstoffe konnten gerade nicht geladen werden.</div>'+fuss;
