function amzUrl(id){ return BUNDLE_ASIN[id]?('https://www.amazon.de/dp/'+BUNDLE_ASIN[id]+'?tag=rootindex-21'):''; }
/* Eine Rangfolge setzt voraus, dass ALLE Kandidaten bewertet sind.
   Seit Supplements keinen Lebensmittel-Score mehr bekommen (Clean_Score = NULL),
   ergibt "num(b)-num(a)" fuer zwei leere Werte 0 -> die Sortierung passiert nicht,
   und das erste Produkt der handgepflegten ID-Liste bekaeme das TOP-Siegel,
   nur weil es zuerst getippt wurde. Das ist eine Empfehlung ohne Grundlage.
   Regel: Rangfolge und TOP-Siegel nur, wenn jedes Produkt im Block einen Score hat.
   Sonst: alle Kandidaten gleichrangig zeigen, keine Auswahl treffen. */
function bundleRangbar(list){ return list.every(function(p){ return num(p.clean_score)!=null; }); }
const BUNDLE_KEIN_RANG='<div style="font-size:11px;color:var(--muted);background:var(--k-f4f5f4);border-radius:7px;padding:5px 8px;margin-bottom:6px;line-height:1.35">Wir zeigen hier <b>keine Reihenfolge</b>. Nahrungsergänzung bekommt <b>keinen Root Index</b> – eine Kapsel ist kein Lebensmittel. Wir prüfen stattdessen im <b>Dosis-Check</b>, ob die Dosis innerhalb der EFSA-Grenzwerte liegt. Eine Rangfolge ergibt das nicht, deshalb nennen wir alle Kandidaten, ohne einen zu bevorzugen.</div>';
