    +(winner?'<div style="position:absolute;top:7px;left:7px;background:var(--green);color:var(--auf-gruen);font-size:9.5px;font-weight:700;padding:2px 7px;border-radius:999px">TOP</div>':'')
    +(p.clean_score!=null?'<div style="position:absolute;bottom:6px;right:6px;background:var(--card);border-radius:50%;padding:2px;box-shadow:0 1px 5px rgba(0,0,0,.25)">'+donut(num(p.clean_score),farbe(p.bewertung),50)+'</div>':'')
    +'</div>'
