function _zkDeckung(p){
  const txt=((p.naehrstoffe||[]).map(n=>n.n).join(' ')+' '+(p.zutaten||[]).map(z=>z.name).join(' ')).toLowerCase();
  const has=re=>re.test(txt);
  const items=[['Magnesium',has(/magnesium/)],['Omega-3',has(/omega|epa|dha/)],['Vitamin B1',has(/\bb1\b|thiamin/)],['Mönchspfeffer',has(/m[öo]nchspfeffer|vitex/)]];
  const n=items.filter(x=>x[1]).length;
  return {n, html:'<div style="display:flex;flex-wrap:wrap;gap:4px 12px">'+items.map(([l,ok])=>'<span style="white-space:nowrap;font-size:11px;color:'+(ok?'var(--k-166534)':'var(--k-b0aca4)')+'">'+(ok?'✓':'✗')+' '+l+'</span>').join('')+'</div>'};
}
function zyklusKomplexeHtml(){
  let list=(ALL||[]).filter(p=>String(p.unterkategorie||'').toLowerCase()==='zyklus-komplex' && num(p.clean_score)!=null);
  if(list.length<2) return '';
  list.sort((a,b)=>num(b.clean_score)-num(a.clean_score)); list=list.slice(0,2);
  const row=(p,i)=>{
    const d=_zkDeckung(p); const amz=p.produktlink||'';
    return '<div style="display:flex;gap:11px;align-items:flex-start;padding:11px 0;border-top:'+(i>0?'1px solid var(--line)':'none')+'">'
      +'<div onclick="detailById(\''+p.id+'\')" style="cursor:pointer;flex:0 0 auto">'+donut(num(p.clean_score),farbe(p.bewertung),56)+'</div>'
      +'<div style="flex:1;min-width:0;cursor:pointer" onclick="detailById(\''+p.id+'\')">'
      +'<div style="font-weight:700;font-size:14px;line-height:1.2">'+esc(p.name)+'</div>'
      +'<div style="font-size:11.5px;color:var(--muted);margin-bottom:4px">'+esc(p.marke||'')+' · deckt <b>'+d.n+'/4</b> belegten Wirkstoffe</div>'
      +'<div style="line-height:1.7">'+d.html+'</div></div>'
      +(amz?'<a href="'+esc(amz)+'" target="_blank" rel="noopener nofollow sponsored" onclick="event.stopPropagation()" style="flex:0 0 auto;text-decoration:none;background:var(--green);color:var(--auf-gruen);font-size:12.5px;font-weight:700;padding:8px 14px;border-radius:9px">Hier kaufen ↗</a>':'')
      +'</div>';
  };
  return '<div style="background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:12px;box-shadow:var(--shadow)">'
    +'<div style="font-weight:800;font-size:16px">Zyklus-Komplexe im Vergleich</div>'
    +'<div style="font-size:12.5px;color:var(--muted);margin:3px 0 8px">Häufig enthalten: <b>Magnesium · Omega-3 · Vitamin B1 · Mönchspfeffer</b>. Fertige Komplexe decken das oft nur <b>teilweise</b> ab – hier siehst du, was wirklich drin ist. Vollständig abgedeckt bekommst du es mit den sauberen Einzelprodukten oben. <span style="color:var(--k-8a8072)">· Anzeige</span></div>'
    +list.map(row).join('')
    +'<div style="font-size:10.5px;color:var(--k-8a8072);margin-top:10px">Anzeige · Amazon-Partner-Links: Preis für dich unverändert · Bewertung bleibt unabhängig. Keine medizinische Beratung.</div>'
    +'</div>';
}
