async function ktSend(){
  const g=function(id){return document.getElementById(id);}; const msg=g('ktMsg');
  const t=(document.querySelector('input[name=ktTyp]:checked')||{}).value||'frage';
  const p={ typ:t, name:g('ktName').value.trim(), email:g('ktEmail').value.trim() };
  if(t==='frage'){ p.nachricht=g('ktNachricht').value.trim(); if(!p.nachricht){ msg.style.color='var(--k-dc2626)'; msg.textContent='Bitte deine Frage eingeben.'; return; } }
  else {
    p.produktname=g('ktProd').value.trim(); p.marke=g('ktMarke').value.trim(); p.link=g('ktLink').value.trim();
    p.barcode=(g('ktBarcode').value||'').replace(/[^0-9]/g,'');
    if(!p.barcode || p.barcode.length<8){ msg.style.color='var(--k-dc2626)'; msg.textContent='Bitte den Barcode eingeben oder scannen – ohne EAN können wir das Produkt nicht eindeutig prüfen.'; return; }
    if(!p.produktname){ msg.style.color='var(--k-dc2626)'; msg.textContent='Bitte den Produktnamen eingeben.'; return; }
  }
  msg.style.color='var(--k-374151)'; msg.textContent='⏳ senden…';
  try{ const {error}=await client.rpc('cb_kontakt_senden',{p:p}); if(error) throw error;
    msg.style.color='var(--k-16a34a)'; msg.textContent='✓ Danke! Deine '+(t==='produkt'?'Produktanfrage':'Nachricht')+' ist eingegangen.';
    setTimeout(function(){ const ov=document.getElementById('kontaktOv'); if(ov) ov.remove(); }, 1400);
  }catch(e){ msg.style.color='var(--k-dc2626)'; msg.textContent='Fehler: '+(e.message||'bitte spaeter erneut'); }
}
async function ktScanStart(){
  const msg=document.getElementById('ktMsg');
  try{
    _startScan("ktReader", async function(code){
      const f=document.getElementById('ktBarcode'); if(f) f.value=code;
      stopScan();
      if(msg){ msg.style.color='var(--k-2e7d32)'; msg.textContent='✓ Barcode '+code+' erkannt.'; }
      try{
        const {data}=await client.rpc("produkt_by_ean",{p_ean:code});
        if(data&&data.id&&msg){ msg.style.color='var(--k-b45309)'; msg.textContent='Dieses Produkt ist bereits im Katalog: '+data.name; return; }
      }catch(e){}
      try{
        const r=await fetch('https://world.openfoodfacts.org/api/v2/product/'+encodeURIComponent(code)+'.json');
        const j=await r.json();
        if(j&&j.status===1&&j.product){
          const pn=document.getElementById('ktProd'), mk=document.getElementById('ktMarke');
          if(pn&&!pn.value) pn.value=j.product.product_name_de||j.product.product_name||'';
          if(mk&&!mk.value) mk.value=(j.product.brands||'').split(',')[0].trim();
          if(msg){ msg.style.color='var(--k-2e7d32)'; msg.textContent='✓ Bei Open Food Facts gefunden – Name/Marke vorbelegt, bitte prüfen.'; }
        }
      }catch(e){}
    });
  }catch(e){ if(msg){ msg.style.color='var(--k-dc2626)'; msg.textContent='Kamera nicht verfügbar: '+e.message; } }
}
async function ktErledigt(id){ try{ await client.rpc("cb_admin_kontakt_erledigt",{p_id:id}); }catch(e){} loadFreigabe(); }
function ktAnlegen(i){ const x=(window._ktList||[])[i]; if(!x){ openFgEditor(null); return; } openFgEditor(null, {name:x.produktname, marke:x.marke, ean:x.barcode}); }
function ktAntwort(i){ const x=(window._ktList||[])[i]; if(!x||!x.email) return; const betr=x.typ==='produkt'?('Deine Produktanfrage: '+(x.produktname||'')):'Deine Nachricht an Root Index'; const body='Hallo'+(x.name?' '+x.name:'')+',\r\n\r\ndanke fuer deine Nachricht an Root Index.\r\n\r\n'; window.location.href='mailto:'+encodeURIComponent(x.email)+'?subject='+encodeURIComponent(betr)+'&body='+encodeURIComponent(body); }
/* ===== App & Konto auf der Profilseite (Ralph 19.09.2026) =====
   "was ist bei einstellungen noch enthalten? darstellung und der hinweis auf
   angemeldet. koennen wir beide in mein profil verschieben? dann koennte
   einstellungen aus dem menue entfernt werden, oder?"

   Gemessen, was wirklich drin stand: Darstellung, zwei RIKI-Schalter, Konto
   (angemeldet als, Abo, Abmelden, Konto loeschen) - und viermal dasselbe, was
   seit dem Faecher schon unter "Root Index" und "Rechtliches" steht (Wiki,
   Methode, Kontakt, Impressum/Datenschutz/AGB). Die Doppelten sind ersatzlos
   weg, der Rest steht hier. Damit ist die Schublade leer und der Punkt
   "Einstellungen" aus dem Faecher verschwunden - genau wie Ralph vermutet hat. */
function pfAppRender(){
  var box=document.getElementById("pfAppBox"); if(!box) return;
  var seg=function(titel, hinweis, werte, aktiv, ruf, aus){
    return '<div style="padding:2px 0 14px'+(aus?';opacity:.45;pointer-events:none':'')+'">'
      +'<div style="font-weight:600;font-size:13.5px;margin-bottom:2px">'+titel+'</div>'
      +(hinweis?'<div style="font-size:11.5px;color:var(--muted);margin-bottom:7px">'+hinweis+'</div>':'<div style="height:7px"></div>')
      +'<div style="display:flex;gap:6px">'
      + werte.map(function(o){
          var an=(aktiv===o[0]);
          return '<button onclick="'+ruf.replace('%W%', (typeof o[0]==='boolean')?(o[0]?'true':'false'):("'"+o[0]+"'"))+'" style="flex:1;padding:9px 4px;border-radius:9px;font-size:12.5px;font-weight:600;cursor:pointer;'
               + 'border:1px solid '+(an?'var(--green)':'var(--line)')+';'
               + 'background:'+(an?'var(--greenlt)':'var(--card)')+';'
               + 'color:'+(an?'var(--greendk)':'var(--ink)')+'">'+o[1]+'</button>';
        }).join('')
      +'</div></div>';
  };
  var html='';
  html+=seg('Darstellung',
            'Automatisch folgt dem Gerät – wer sein Handy auf dunkel gestellt hat, will nicht von jeder App neu gefragt werden.',
            [['auto','Automatisch'],['hell','Hell'],['dunkel','Dunkel']],
            (window.riThemeWahl||'auto'), "riThemeSetzen(%W%)");

  var rAn = (typeof window.rikiSichtbar==='function') ? window.rikiSichtbar() : true;
  html+=seg('RIKI · der Begleiter unten rechts', '', [[true,'An'],[false,'Aus']], rAn, "rikiSichtSetzen(%W%)");
  var iAn = (typeof window.rikiIntroAn==='function') ? window.rikiIntroAn() : true;
  html+=seg('RIKI erklärt auf der Startseite, was Root Index ist', '',
            [[true,'An'],[false,'Aus']], iAn, "rikiIntroSetzen(%W%)", !rAn);

  html+='<div style="border-top:1px solid var(--line);margin:4px 0 12px"></div>';
  /* Abo, Abmelden und Konto loeschen stehen im Faecher unter "Abo & Konto"
     (Ralph 19.09.) - hier stuenden sie ein zweites Mal. Nur wer angemeldet
     ist, sieht ueberhaupt etwas; fuer Gaeste bleibt der Anmeldeweg. */
  if(ME){
    html+='<div style="font-size:12.5px;color:var(--muted)">Angemeldet als <b style="color:var(--ink)">'+esc(ME.email||'')+'</b><br>Abo, Abmelden und Konto löschen stehen im Menü unter „Abo &amp; Konto".</div>';
  } else {
    html+='<button onclick="openLogin()" style="display:block;width:100%;text-align:left;padding:11px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);font-size:14px;cursor:pointer">🔑 Anmelden</button>';
  }

  box.innerHTML=html;
}
if(typeof window!=='undefined'){ window.pfAppRender=pfAppRender; }
function legalOpen(which){
  let ov=document.getElementById("legalOv"); if(ov) ov.remove();
  ov=document.createElement("div"); ov.id="legalOv";
  ov.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;justify-content:center;z-index:10001";
  ov.onclick=e=>{ if(e.target===ov) ov.remove(); };
  const H=t=>`<h3 style="font-size:15px;color:var(--green);margin:16px 0 4px">${t}</h3>`;
  const P=t=>`<p style="font-size:13.5px;line-height:1.55;color:var(--ink);margin:.2em 0">${t}</p>`;
  const impressum = H("Impressum")+`<p style="font-size:12px;color:var(--muted)">Angaben gemäß § 5 DDG</p>`
    +P("<b>Ralph Denk</b><br>Root Index (Einzelunternehmen)<br>Auweg 23<br>84103 Postau<br>Deutschland")
    +H("Kontakt")+P("E-Mail: kontakt@root-index.de<br>Alternativ über das Kontaktformular in der App (Menü „Mehr“ → Kontakt). Wir antworten in der Regel innerhalb von 48 Stunden.")
    +H("Umsatzsteuer")+P("Kleinunternehmerin gemäß § 19 UStG – es wird keine Umsatzsteuer ausgewiesen.")
    +H("Verantwortlich i.S.d. § 18 Abs. 2 MStV")+P("Ralph Denk, Anschrift wie oben.")
    +H("Werbung &amp; Partnerlinks")+P("Root Index ist Teilnehmer des Amazon-Partnerprogramms. <b>Als Amazon-Partner verdienen wir an qualifizierten Verkäufen.</b> Mit „Anzeige“ gekennzeichnete Links sind Partnerlinks – der Preis ändert sich für dich dadurch nicht. <b>Partnerlinks haben keinerlei Einfluss auf den Root Index.</b> Ein Produkt wird bewertet, bevor überhaupt geprüft wird, ob es einen Partnerlink gibt; kein Hersteller kann eine Bewertung kaufen oder beeinflussen.")
    +H("Datenquellen &amp; Lizenzen")+P("Nährwerte generischer Lebensmittel stammen aus dem <b>Bundeslebensmittelschlüssel (BLS 4.0)</b>, © Max Rubner-Institut, Bundesforschungsinstitut für Ernährung und Lebensmittel, lizenziert unter <b>CC BY 4.0</b> (creativecommons.org/licenses/by/4.0). Ergänzend nutzen wir Daten von <b>Open Food Facts</b> (Datenbank lizenziert unter <b>ODbL 1.0</b>, Inhalte unter CC BY-SA 3.0) sowie Herstellerangaben und Etikettfotos unserer Nutzerinnen und Nutzer. Die Quelle steht bei jedem Produkt unter dem Index. Wissenschaftliche Grundlagen: EFSA, WHO, EU-VO 1333/2008 und 432/2012, IARC, DGE.")
    +H("Verbraucherstreitbeilegung")+P("Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.")
    +H("Haftung für Inhalte")+P("Die Inhalte wurden mit größter Sorgfalt erstellt. Für Richtigkeit, Vollständigkeit und Aktualität übernehmen wir keine Gewähr. Bewertungen und Informationen dienen der Orientierung und stellen keine medizinische oder ernährungstherapeutische Beratung dar.")
    +H("Haftung für Links")+P("Unser Angebot enthält ggf. Links zu externen Websites Dritter, auf deren Inhalte wir keinen Einfluss haben. Dafür ist stets der jeweilige Anbieter verantwortlich.")
    +H("Urheberrecht")+P("Die erstellten Inhalte unterliegen dem deutschen Urheberrecht.");
  const ds = H("Datenschutzerklärung – Root Index")
    +P("<i>Stand: September 2026</i>")
    +H("1. Verantwortlicher")
    +P("Verantwortlich für die Verarbeitung personenbezogener Daten ist:")
    +P("Ralph Denk – Root Index<br>Auweg 23<br>84103 Postau<br>Deutschland<br>E-Mail: <a href=\"mailto:kontakt@root-index.de\">kontakt@root-index.de</a>")
    +P("Bei Fragen zum Datenschutz oder zur Ausübung deiner Rechte kannst du dich an diese Adresse wenden.")
    +P("Diese Datenschutzerklärung betrifft das Webangebot unter root-index.de. Zusätzliche Datenverarbeitungen einer nativen Smartphone-App werden vor deren Nutzung gesondert erläutert.")
    +H("2. Welche Daten wir verarbeiten")
    +P("Je nach Nutzung verarbeiten wir insbesondere:")
    +P("• <b>Kontodaten:</b> E-Mail-Adresse, Nutzerkennung, Anmelde- und Sicherheitseinstellungen sowie gegebenenfalls deinen Namen.<br>• <b>Profil- und Nutzungsdaten:</b> beispielsweise Geburtsdatum, Ernährungsform, Favoriten, Einkaufslisten, eigene Rezepte und Pläne.<br>• <b>Gesundheitsbezogene Daten:</b> beispielsweise Ernährungstagebuch, Gewicht, Körpermaße, Training, Schlaf, Schritte, Supplemente, Zyklus und freiwillige Angaben zu Erkrankungen.<br>• <b>Beiträge und Anfragen:</b> hochgeladene Fotos, Produktangaben, Fragen an RIKI, Kontaktanfragen und zugehörige Verarbeitungsergebnisse.<br>• <b>Vertragsdaten:</b> gewählter Tarif, Abonnementstatus, Zahlungs- und Rechnungsinformationen sowie Kündigungs- und Widerrufserklärungen.<br>• <b>Technische Daten:</b> beispielsweise IP-Adresse, Zeitpunkt und Ziel eines Zugriffs, Browserinformationen und Fehlermeldungen.<br>• <b>Einwilligungsnachweise:</b> Inhalt, Zeitpunkt und Zuordnung erteilter oder widerrufener Einwilligungen.")
    +P("Nicht jede dieser Datenarten fällt bei jedem Besuch an.")
    +H("3. Zwecke und Rechtsgrundlagen")
    +P("Wir verarbeiten personenbezogene Daten für folgende Zwecke:")
    +P("• Zur Bereitstellung deines Kontos und der von dir gewünschten Funktionen sowie zur Vertragsabwicklung auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO.<br>• Auf Grundlage deiner Einwilligung nach Art. 6 Abs. 1 lit. a DSGVO, soweit eine Verarbeitung freiwillig und einwilligungsbedürftig ist.<br>• Bei Gesundheitsdaten zusätzlich auf Grundlage deiner ausdrücklichen Einwilligung nach Art. 9 Abs. 2 lit. a DSGVO.<br>• Zur Erfüllung gesetzlicher Pflichten, beispielsweise steuerlicher Aufbewahrungspflichten, nach Art. 6 Abs. 1 lit. c DSGVO.<br>• Zur sicheren Bereitstellung, Fehlerbehebung und Abwehr von Missbrauch nach Art. 6 Abs. 1 lit. f DSGVO. Unser berechtigtes Interesse besteht darin, das Angebot zuverlässig zu betreiben und vor unbefugten Zugriffen zu schützen.")
    +P("Welche Grundlage einschlägig ist, hängt vom jeweiligen Verarbeitungsvorgang ab.")
    +H("4. Nutzerkonto und Mindestalter")
    +P("Root Index richtet sich an Personen ab 16 Jahren.")
    +P("Für kontogebundene Funktionen benötigen wir insbesondere deine E-Mail-Adresse und technische Anmeldedaten. Ohne diese Angaben können wir kein persönliches Konto bereitstellen.")
    +P("Weitere Angaben sind nur erforderlich, soweit du die darauf beruhende Funktion nutzen möchtest. Beispielsweise benötigen individuelle Bedarfsberechnungen die hierfür abgefragten Körper- und Aktivitätsangaben.")
    +P("Die datenschutzrechtliche Einwilligung ist von der Zustimmung zum Abschluss eines kostenpflichtigen Abonnements zu unterscheiden. Für Verträge Minderjähriger gelten zusätzlich die gesetzlichen Voraussetzungen und die AGB.")
    +H("5. Gesundheitsdaten und persönliche Auswertungen")
    +P("Gesundheitsbezogene Angaben verwenden wir zur Bereitstellung der von dir gewählten Dokumentations-, Berechnungs- und Auswertungsfunktionen.")
    +P("Die Eingabe solcher Angaben oder die Zustimmung zu den AGB ersetzt keine ausdrückliche Gesundheitseinwilligung.")
    +P("Du kannst eine erteilte Einwilligung jederzeit mit Wirkung für die Zukunft widerrufen, insbesondere per E-Mail an <a href=\"mailto:kontakt@root-index.de\">kontakt@root-index.de</a> oder über die dafür angebotene Funktion in der Anwendung.")
    +P("Die Rechtmäßigkeit der Verarbeitung vor dem Widerruf bleibt unberührt. Anschließend beenden wir die auf dieser Einwilligung beruhende Verarbeitung und löschen die betreffenden Daten, soweit keine gesetzliche Ausnahme eine weitere Speicherung erlaubt.")
    +P("Funktionen, die diese Daten benötigen, stehen danach nicht mehr oder nur eingeschränkt zur Verfügung.")
    +P("<b>Ohne Gesundheitseinwilligung</b> bleiben insbesondere nutzbar: Produktsuche und Barcode-Scan, Produktbewertungen, Favoriten, Einkaufslisten, Rezepte und Fragen an RIKI ohne persönlichen Gesundheitsbezug.")
    +P("<b>Beim Widerruf werden sofort gelöscht:</b> Ernährungstagebuch, Gewichtsverlauf, Körpermaße, Supplemente, Wasser-, Schlaf- und Schrittdaten, Tagesform, Trainingsdaten und Trainingsprofil, Zielverlauf sowie die Alters- und Körperangaben in deinem Profil.")
    +P("<b>Sicherungskopien:</b> Unsere Datenbank wird automatisch gesichert. Diese Sicherungen werden rollierend überschrieben und sind spätestens nach 30 Tagen gelöscht. Bis dahin werden sie nicht verwendet, außer zur Wiederherstellung nach einem technischen Ausfall; gelöschte Daten werden dabei nicht wieder aktiviert.")
    +H("6. Hosting und Datenhaltung")
    +P("<b>INWX (Website und E-Mail)</b>")
    +P("Unsere Website und unser E-Mail-Postfach werden bei der INWX GmbH, Prinzessinnenstraße 30, 10969 Berlin, auf Servern in Deutschland betrieben. Bei einem Seitenaufruf werden technische Verbindungsdaten, insbesondere die IP-Adresse und Angaben zum Abruf, verarbeitet.")
    +P("Die Verarbeitung dient der Auslieferung und Sicherheit der Website. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO. Mit INWX besteht ein Auftragsverarbeitungsvertrag nach Art. 28 DSGVO.")
    +P("<b>GitHub (Quellcode und Veröffentlichung)</b>")
    +P("Den Programmcode der Website verwalten wir bei GitHub (GitHub, Inc., USA). Von dort wird er automatisch auf unseren Webserver bei INWX übertragen. Dabei werden keine Daten von Besucherinnen und Besuchern an GitHub übermittelt. Die Website selbst wird ausschließlich über INWX ausgeliefert. Weitere Informationen: <a href=\"https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement\" target=\"_blank\" rel=\"noopener\">GitHub-Datenschutzerklärung</a>.")
    +P("<b>Supabase</b>")
    +P("Für Anmeldung, Datenbank, Dateispeicherung und serverseitige Funktionen verwenden wir Supabase. Dabei werden die für die jeweilige Funktion erforderlichen Konto-, Inhalts- und technischen Daten verarbeitet.")
    +P("Die Rechtsgrundlagen richten sich nach dem jeweiligen Zweck; für Gesundheitsdaten gilt zusätzlich Abschnitt 5.")
    +P("Vertragspartner ist die Supabase, Inc., USA, als Auftragsverarbeiter. Unser Projekt liegt in der Region EU (Frankfurt am Main, eu-central-1); dort werden Datenbank, Dateien und Sicherungen gespeichert. Grundlage ist der Auftragsverarbeitungsvertrag von Supabase nach Art. 28 DSGVO einschließlich EU-Standardvertragsklauseln. Für Betrieb, Protokolle und Support können Mitarbeitende und Unterauftragnehmer von Supabase auch aus Drittländern, insbesondere den USA, zugreifen.")
    +P("Ein europäischer Datenbankstandort bedeutet nicht automatisch, dass sämtliche Verarbeitung ausschließlich innerhalb der EU stattfindet.")
    +H("7. Speicherung auf deinem Gerät und externe Programmbibliotheken")
    +P("Die Anwendung speichert Informationen auf deinem Gerät, beispielsweise zur Aufrechterhaltung deiner Anmeldung, für gewählte Einstellungen und für den Betrieb der installierbaren Webanwendung.")
    +P("Soweit diese Speicherung oder das Auslesen unbedingt erforderlich ist, um einen ausdrücklich gewünschten Dienst bereitzustellen, erfolgt dies auf Grundlage von § 25 Abs. 2 Nr. 2 TDDDG. Für darüber hinausgehende einwilligungsbedürftige Zugriffe ist eine vorherige Einwilligung erforderlich.")
    +P("Die anschließende Verarbeitung personenbezogener Daten richtet sich zusätzlich nach der DSGVO.")
    +P("Konkret speichern wir im lokalen Speicher deines Browsers: deine Anmeldesitzung (bis zur Abmeldung), Anzeige-Einstellungen wie Filter, Dunkelmodus oder Ansicht (bis du sie änderst oder die Browserdaten löschst) sowie über den Service Worker eine Kopie der Programmdateien für schnelles Laden und Offline-Betrieb (wird bei jeder neuen Version ersetzt). Wir setzen keine Werbe- oder Analyse-Cookies.")
    +P("Programmbibliotheken werden teilweise über jsDelivr geladen. Dabei erhält die Auslieferungsinfrastruktur technische Verbindungsdaten, insbesondere deine IP-Adresse. Zweck ist die Bereitstellung der benötigten Programmfunktionen.")
    +P("Über jsDelivr (cdn.jsdelivr.net) laden wir die Anmelde- und Datenbankbibliothek von Supabase und die Barcode-Erkennung (Quagga2). jsDelivr nutzt Auslieferungsnetzwerke wie Cloudflare und Fastly, auch mit Sitz in den USA. Wir speichern dabei nichts. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; unser berechtigtes Interesse ist die schnelle und zuverlässige Bereitstellung der Programmfunktionen. Für Übermittlungen in die USA gilt Abschnitt 17.")
    +H("8. Kamera, Barcode-Scan und Fotos")
    +P("Beim Barcode-Scan wird das Kamerabild auf deinem Gerät ausgewertet, um die Produktnummer zu erkennen. Die erkannte Nummer wird anschließend für die Produktsuche verwendet.")
    +P("Davon zu unterscheiden sind Funktionen, bei denen du Fotos ausdrücklich zur Verarbeitung hochlädst, beispielsweise Etikett-, Produkt- oder Rezeptfotos. Diese Dateien werden an unsere Server übertragen und dort zur Bearbeitung deiner Anfrage gespeichert und ausgewertet.")
    +P("Die Verarbeitung erfolgt, soweit zur angeforderten Funktion erforderlich, auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO. Eine darüber hinausgehende Verwendung benötigt eine gesonderte Rechtsgrundlage.")
    +P("Bitte fotografiere keine Personen, privaten Dokumente oder sonstigen nicht benötigten persönlichen Informationen.")
    +P("Aus eingereichten Produktinformationen können Einträge für den öffentlichen Produktkatalog entstehen.")
    +P("Veröffentlicht werden dabei nur Produktangaben (Name, Marke, Zutaten, Nährwerte) und gegebenenfalls ein Produktbild. Dein Name, deine E-Mail-Adresse oder andere Kontodaten werden nie veröffentlicht. Originalfotos von Etiketten bewahren wir bis zur Prüfung des Produkts auf, längstens 12 Monate; danach werden sie gelöscht. Fotos von Vorräten oder Rezepten dienen nur der jeweiligen Anfrage und werden nicht veröffentlicht.")
    +H("9. RIKI und KI-gestützte Funktionen")
    +P("RIKI unterstützt beispielsweise beim Auslesen von Etiketten, bei Rezeptfunktionen und bei der Beantwortung von Fragen.")
    +P("Dabei werden die für die jeweilige Anfrage benötigten Eingaben verarbeitet, etwa Fotos, Texte, Produktangaben und der zugehörige Anwendungskontext. Für personalisierte Funktionen können außerdem Profil- oder Tagebuchinformationen relevant sein.")
    +P("Rechtsgrundlage für die zur angeforderten Funktion erforderliche Verarbeitung gewöhnlicher personenbezogener Daten ist Art. 6 Abs. 1 lit. b DSGVO. Die Verarbeitung von Gesundheitsdaten muss zusätzlich von einer ausdrücklichen, ausreichend konkreten Einwilligung gedeckt sein.")
    +P("<b>Eingesetzter KI-Anbieter:</b> Anthropic PBC, USA (KI-Modelle „Claude“). Andere KI-Anbieter setzen wir derzeit nicht ein. Je Funktion werden übermittelt:")
    +P("• Etikett- und Produktauswertung: Fotos und Texte von Etiketten sowie Produktangaben.<br>• Fragen an RIKI: dein Fragetext und ein auf die Frage beschränkter Seitenkontext.<br>• Rezeptvorschläge: die von dir genannten Zutaten, Mahlzeit, Ernährungsform und dein täglicher Kalorienbedarf.<br>• Vorrats- und Rezeptfotos: die von dir hochgeladenen Fotos.<br>• Persönliche Wochenempfehlung: zusammengefasste Angaben zu deinen Ess- und Trainingsgewohnheiten. Diese Funktion nutzt Gesundheitsdaten und steht nur mit deiner Gesundheitseinwilligung zur Verfügung.")
    +P("Einzelne Tagebucheinträge, Gewicht, Körpermaße oder Angaben zu Erkrankungen übermitteln wir nicht an Anthropic; bei der Wochenempfehlung werden nur zusammengefasste Werte übertragen. Die Übermittlung in die USA erfolgt auf Grundlage der Vertrags- und Datenschutzbedingungen von Anthropic einschließlich EU-Standardvertragsklauseln. Anthropic verwendet diese Daten nicht zum Training seiner Modelle und speichert sie nur für kurze Zeit zur Missbrauchskontrolle, derzeit höchstens 30 Tage.")
    +H("10. Spracheingabe")
    +P("Wenn du die Spracheingabe aktivierst, wird die Spracherkennungsfunktion deines Browsers oder Betriebssystems verwendet. Je nach eingesetztem System kann Sprache dabei an dessen Anbieter übertragen werden.")
    +P("Der erkannte Text wird anschließend wie eine eingegebene Textanfrage verarbeitet.")
    +P("Wir nutzen dafür die Spracherkennung, die dein Browser bereitstellt (Web Speech API). In Google Chrome wird die Sprachaufnahme dabei an Google (Google LLC, USA / Google Ireland Ltd.) übertragen, in Safari an Apple; andere Browser können eigene Dienste nutzen. Root Index selbst erhält und speichert keine Audiodaten, sondern nur den erkannten Text. Die Aufnahme startet erst, wenn du das Mikrofon-Symbol antippst und dein Browser den Mikrofonzugriff freigibt. Rechtsgrundlage ist deine Einwilligung (Art. 6 Abs. 1 lit. a DSGVO), die du durch das Starten der Spracheingabe erteilst. Du kannst stattdessen jederzeit die Texteingabe verwenden.")
    +H("11. Open Food Facts und externe Produktdaten")
    +P("Für die Produktsuche und die Ergänzung von Produktinformationen verwenden wir unter anderem Open Food Facts (Open Food Facts Association, Frankreich).")
    +P("Bei einer direkten Anfrage deines Browsers erhält Open Food Facts die gesuchte Produktnummer und technische Verbindungsdaten, insbesondere deine IP-Adresse. Erfolgt die Anfrage über unseren Server, erhält Open Food Facts grundsätzlich die Verbindungsdaten dieses Servers.")
    +P("Auch beim direkten Laden externer Produktbilder, insbesondere von Open Food Facts, entstehen Verbindungen zum jeweiligen Bildanbieter.")
    +P("Die Verarbeitung dient der angeforderten Produktsuche und Produktanzeige. Rechtsgrundlage ist Art. 6 Abs. 1 lit. b DSGVO, soweit die Verarbeitung dafür erforderlich ist.")
    +H("12. Zahlungen über Stripe")
    +P("Für Zahlungen zu Root Index Premium verwenden wir Stripe. Zahlungsinformationen gibst du im Zahlungsprozess bei Stripe ein.")
    +P("Zur Vertrags- und Zahlungsabwicklung werden je nach Vorgang insbesondere Kontakt-, Rechnungs-, Zahlungs- und Transaktionsdaten verarbeitet. Wir erhalten beziehungsweise können die für die Verwaltung erforderlichen Informationen einsehen, beispielsweise Kunden- und Abonnementkennungen, Zahlungsstatus, Beträge und Rechnungsinformationen. Vollständige Karten- oder Kontodaten sehen und speichern wir nicht.")
    +P("Rechtsgrundlagen sind Art. 6 Abs. 1 lit. b DSGVO für die Vertragsabwicklung und Art. 6 Abs. 1 lit. c DSGVO für gesetzliche Pflichten.")
    +P("Stripe verarbeitet bestimmte Daten auch in eigener Verantwortung, beispielsweise zur Betrugsprävention und zur Erfüllung eigener gesetzlicher Verpflichtungen.")
    +P("Vertragspartner ist die Stripe Payments Europe, Ltd., 1 Grand Canal Street Lower, Dublin 2, Irland. Stripe kann Daten an die Stripe, Inc. in den USA übermitteln; diese ist unter dem EU-US Data Privacy Framework zertifiziert, ergänzend gelten EU-Standardvertragsklauseln. Zur Verfügung stehen die im Bezahlvorgang angezeigten Zahlungsarten, zum Beispiel Kreditkarte.")
    +P("Weitere Informationen: <a href=\"https://stripe.com/de/privacy\" target=\"_blank\" rel=\"noopener\">Stripe-Datenschutzerklärung</a>.")
    +H("13. Kontakt, Vertragsnachrichten und Newsletter")
    +P("Wenn du uns kontaktierst, verarbeiten wir deine Kontaktdaten und den Inhalt deiner Nachricht zur Bearbeitung deines Anliegens.")
    +P("Bei vertragsbezogenen Anfragen beruht dies auf Art. 6 Abs. 1 lit. b DSGVO, bei sonstigen Anfragen auf unserem berechtigten Interesse an deren Bearbeitung nach Art. 6 Abs. 1 lit. f DSGVO.")
    +P("Anmelde-, Sicherheits- und Vertragsnachrichten werden zur Bereitstellung des Dienstes beziehungsweise zur Erfüllung gesetzlicher Pflichten versandt.")
    +P("Unser Postfach und der Versand aller E-Mails, auch der Anmelde- und Bestätigungs-E-Mails, laufen über die Server der INWX GmbH in Deutschland (Auftragsverarbeitung, siehe Abschnitt 6). Kontaktanfragen löschen wir 12 Monate nach Abschluss der Bearbeitung, soweit keine Aufbewahrungspflicht besteht.")
    +P("Einen Newsletter versenden wir derzeit nicht. Sollte er eingeführt werden, erfolgt der Versand nur auf Grundlage deiner vorherigen Einwilligung mit Bestätigung per E-Mail; die Einwilligung kannst du jederzeit für die Zukunft widerrufen. Öffnungs- oder Klickmessungen finden nicht statt.")
    +H("14. Push-Benachrichtigungen")
    +P("Wenn du Push-Benachrichtigungen aktivierst, werden technische Zustellinformationen verarbeitet, insbesondere eine Zustelladresse und zugehörige Schlüssel. An der Zustellung kann der Push-Dienst deines Browser- oder Betriebssystemanbieters beteiligt sein.")
    +P("Du kannst die Berechtigung in den Einstellungen deines Browsers oder Geräts zurücknehmen.")
    +P("Wir senden Benachrichtigungen derzeit nur zu Änderungen an einer gemeinsam genutzten Einkaufsliste und zum bevorstehenden Ende deiner Premium-Testphase. Benachrichtigungen enthalten keine Gesundheitsinformationen. Beteiligt sind je nach Gerät die Push-Dienste von Google, Mozilla, Microsoft oder Apple. Rechtsgrundlage ist deine Einwilligung (Art. 6 Abs. 1 lit. a DSGVO in Verbindung mit § 25 Abs. 1 TDDDG), die du beim Aktivieren erteilst. Die Zustellinformationen löschen wir, sobald du die Benachrichtigungen abschaltest oder dein Konto löschst; versandte Benachrichtigungen werden nach 90 Tagen gelöscht.")
    +H("15. Besucherstatistik")
    +P("Root Index enthält eine Funktion zur Zählung von Seitenaufrufen und zur zusammengefassten Zuordnung von Zugriffsquellen, beispielsweise Suchmaschinen oder direkten Aufrufen.")
    +P("Gespeichert werden dabei ausschließlich Summen je Tag, Seitenart und Zugriffsquelle. Es werden weder IP-Adressen noch Cookies, Gerätekennungen oder Nutzerkennungen gespeichert; ein Rückschluss auf einzelne Personen ist nicht möglich. Die Tageswerte bewahren wir bis zu 24 Monate auf. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; unser berechtigtes Interesse ist es, die Nutzung unseres Angebots in anonymer Form zu verstehen. Eine Einwilligung ist nicht erforderlich, da nichts auf deinem Gerät gespeichert oder ausgelesen wird.")
    +P("Zusätzlich speichert unser Hoster INWX technische Server-Protokolle (unter anderem IP-Adresse, Zeitpunkt, abgerufene Adresse) zur Sicherheit und Fehlerbehebung. Wir werten diese nicht zu Statistikzwecken aus; sie werden vom Hoster nach kurzer Zeit automatisch gelöscht.")
    +H("16. Werbung und Partnerlinks")
    +P("Root Index enthält gekennzeichnete Partnerlinks, beispielsweise zu Amazon. Über solche Links kann dem jeweiligen Partner die Vermittlung eines Kaufs zugeordnet werden.")
    +P("Beim Aufruf einer externen Händlerseite verarbeitet deren Betreiber Daten in eigener Verantwortung nach seiner Datenschutzerklärung.")
    +P("Vor einem Klick werden keine Bilder, Skripte oder sonstigen Inhalte von Amazon oder anderen Händlern geladen. Eine Verbindung entsteht erst, wenn du den Link anklickst. Dasselbe gilt für Links zur Google-Suche.")
    +H("17. Empfänger und Verarbeitung außerhalb des Europäischen Wirtschaftsraums")
    +P("Personenbezogene Daten können an die in dieser Erklärung beschriebenen technischen Dienstleister, Zahlungsanbieter und Kommunikationsdienste übermittelt werden. Nicht jeder Empfänger handelt ausschließlich als Auftragsverarbeiter.")
    +P("Weitere Übermittlungen können erforderlich sein, um gesetzliche Verpflichtungen zu erfüllen oder Rechtsansprüche geltend zu machen, auszuüben oder zu verteidigen.")
    +P("Für Übermittlungen außerhalb des Europäischen Wirtschaftsraums müssen die Voraussetzungen der Art. 44 ff. DSGVO erfüllt sein. Je nach Empfänger kommen insbesondere ein einschlägiger Angemessenheitsbeschluss oder geeignete Garantien wie EU-Standardvertragsklauseln in Betracht.")
    +P("Im Einzelnen:")
    +P("• INWX GmbH (Website, E-Mail): Deutschland – keine Drittlandübermittlung.<br>• Open Food Facts Association: Frankreich – keine Drittlandübermittlung.<br>• Supabase, Inc. (Datenbank, Anmeldung): Speicherung in der EU, Zugriffe aus den USA möglich – EU-Standardvertragsklauseln.<br>• Anthropic PBC (KI-Funktionen): USA – EU-Standardvertragsklauseln.<br>• Stripe (Zahlungen): Irland und USA – EU-US Data Privacy Framework und EU-Standardvertragsklauseln.<br>• GitHub, Inc. (Quellcode, keine Besucherdaten): USA – EU-US Data Privacy Framework.<br>• jsDelivr und dessen Auslieferungsnetzwerke (Programmbibliotheken): EU und USA – EU-US Data Privacy Framework bzw. EU-Standardvertragsklauseln der Netzbetreiber.<br>• Push- und Spracherkennungsdienste von Google, Apple, Microsoft oder Mozilla: je nach Gerät USA – EU-US Data Privacy Framework bzw. EU-Standardvertragsklauseln.")
    +P("Informationen zu den jeweils verwendeten Garantien und gegebenenfalls eine Kopie erhältst du auf Anfrage unter <a href=\"mailto:kontakt@root-index.de\">kontakt@root-index.de</a>.")
    +H("18. Speicherdauer und Löschung")
    +P("Wir speichern personenbezogene Daten nur so lange, wie dies für den jeweiligen Zweck erforderlich ist oder gesetzliche Aufbewahrungspflichten bestehen.")
    +P("Kontobezogene Inhalte werden grundsätzlich für die Dauer der Nutzung der jeweiligen Funktionen gespeichert. Nach einer Löschung oder einem Widerruf gelten die gesetzlichen Löschungsanforderungen; erforderliche Vertrags- und Nachweisdaten werden hiervon getrennt behandelt.")
    +P("Für Rechnungen und andere Buchungsbelege gilt regelmäßig eine Aufbewahrungsfrist von acht Jahren, für bestimmte Geschäftsbriefe sechs Jahre und für bestimmte steuerliche Aufzeichnungen zehn Jahre. Die maßgebliche Frist beginnt grundsätzlich mit Ablauf des betreffenden Kalenderjahres; gesetzliche Verlängerungen bleiben möglich.")
    +P("Im Einzelnen:")
    +P("• <b>Konto und Profil:</b> bis zur Löschung deines Kontos. Die Löschung über „Konto löschen“ erfolgt sofort.<br>• <b>Gesundheitsdaten:</b> bis zum Widerruf deiner Gesundheitseinwilligung oder zur Kontolöschung; dann sofortige Löschung (siehe Abschnitt 5).<br>• <b>Etikett- und Produktfotos:</b> bis zur Prüfung des Produkts, längstens 12 Monate. Fotos von Vorräten und Rezepten: nur für die Dauer der Anfrage.<br>• <b>KI-Anfragen und Ergebnisse:</b> solange sie für die jeweilige Funktion benötigt werden, spätestens bis zur Kontolöschung. Beim KI-Anbieter siehe Abschnitt 9.<br>• <b>Kontaktanfragen:</b> 12 Monate nach Abschluss der Bearbeitung.<br>• <b>Technische Protokolle:</b> höchstens 90 Tage.<br>• <b>Einwilligungsnachweise sowie Kündigungs- und Widerrufserklärungen:</b> für die Dauer des Kontos bzw. Vertrags und danach drei Jahre ab Jahresende (regelmäßige Verjährungsfrist), soweit keine längere Aufbewahrungspflicht besteht.<br>• <b>Sicherungskopien:</b> rollierend, spätestens nach 30 Tagen überschrieben.")
    +H("19. Deine Rechte")
    +P("Unter den gesetzlichen Voraussetzungen hast du insbesondere das Recht auf:")
    +P("• Auskunft über deine personenbezogenen Daten und eine Kopie dieser Daten;<br>• Berichtigung unrichtiger und Ergänzung unvollständiger Daten;<br>• Löschung oder Einschränkung der Verarbeitung;<br>• Übertragung der von dir bereitgestellten Daten in einem strukturierten, gängigen und maschinenlesbaren Format, soweit die Voraussetzungen des Art. 20 DSGVO erfüllt sind;<br>• jederzeitigen Widerruf einer Einwilligung mit Wirkung für die Zukunft.")
    +P("Du kannst einer Verarbeitung auf Grundlage von Art. 6 Abs. 1 lit. f DSGVO aus Gründen widersprechen, die sich aus deiner besonderen Situation ergeben. Gegen Direktwerbung kannst du jederzeit ohne Begründung Widerspruch einlegen.")
    +P("Zur Ausübung deiner Rechte genügt eine Nachricht an <a href=\"mailto:kontakt@root-index.de\">kontakt@root-index.de</a>. Soweit erforderlich, bitten wir um geeignete Informationen zur Bestätigung deiner Identität.")
    +H("20. Beschwerderecht und automatisierte Verarbeitung")
    +P("Du kannst dich bei einer Datenschutzaufsichtsbehörde beschweren, insbesondere an deinem gewöhnlichen Aufenthaltsort, deinem Arbeitsplatz oder am Ort des vermuteten Verstoßes.")
    +P("Für private Unternehmen in Bayern ist insbesondere zuständig:")
    +P("Bayerisches Landesamt für Datenschutzaufsicht – BayLDA<br>Postanschrift: Postfach 1349, 91504 Ansbach<br>Website: <a href=\"https://www.lda.bayern.de\" target=\"_blank\" rel=\"noopener\">www.lda.bayern.de</a>")
    +P("Root Index erstellt automatisierte Berechnungen und personalisierte Auswertungen, beispielsweise zu Nährstoffversorgung und Ernährungsgewohnheiten.")
    +P("Diese Berechnungen sind Hinweise und Empfehlungen. Es finden keine ausschließlich automatisierten Entscheidungen statt, die dir gegenüber rechtliche Wirkung entfalten oder dich in ähnlicher Weise erheblich beeinträchtigen (Art. 22 DSGVO). Insbesondere hängen Vertragsschluss, Preis oder Zugang zu Root Index nicht von solchen Auswertungen ab.");
  const agb = H("Allgemeine Geschäftsbedingungen – Root Index Premium")
    +P("<i>Stand: September 2026</i>")
    +H("§ 1 Geltungsbereich und Anbieter")
    +P("Diese Allgemeinen Geschäftsbedingungen gelten für den Abschluss und die Nutzung eines kostenpflichtigen Abonnements „Root Index Premium“ über root-index.de.")
    +P("Anbieter und Vertragspartner ist:")
    +P("<b>Ralph Denk</b><br>Root Index<br>Auweg 23<br>84103 Postau<br>Deutschland<br>E-Mail: kontakt@root-index.de")
    +P("Das Angebot richtet sich an Verbraucher im Sinne des § 13 BGB, die Root Index für private Zwecke nutzen.")
    +P("Diese AGB regeln den unmittelbaren Vertragsabschluss über unsere Website. Für einen gegebenenfalls angebotenen Kauf über einen App-Store werden die dafür geltenden Vertragsbedingungen gesondert angezeigt.")
    +H("§ 2 Mindestalter und Nutzerkonto")
    +P("Root Index richtet sich an Personen ab <b>16 Jahren</b>.")
    +P("Personen, die das 18. Lebensjahr noch nicht vollendet haben, benötigen für den Abschluss eines Premium-Abonnements einschließlich einer kostenlosen Testphase mit anschließendem kostenpflichtigem Abonnement die vorherige Zustimmung ihrer gesetzlichen Vertretung.")
    +P("Die Zustimmung muss den gewählten Tarif, die Zahlungspflicht nach der Testphase und die Laufzeit umfassen. Wir können einen geeigneten Nachweis verlangen. Die gesetzlichen Vorschriften über die Wirksamkeit von Verträgen Minderjähriger bleiben unberührt.")
    +P("Für Premium ist ein persönliches Nutzerkonto erforderlich. Die jeweils verfügbaren Anmeldeverfahren werden bei der Registrierung angezeigt. Angaben zum Alter und zur Berechtigung zum Vertragsabschluss müssen wahrheitsgemäß sein.")
    +H("§ 3 Leistungen von Root Index Premium")
    +P("Root Index ist eine informations- und wissenschaftsbasierte Anwendung zur Bewertung von Lebensmitteln und anderen erfassten Produkten sowie zur Dokumentation und Planung von Ernährung und Training.")
    +P("Der Root Index bewertet Produkte auf einer Skala von 0 bis 100 anhand der jeweils erläuterten Bewertungsmethode. Bewertungen dienen der Orientierung; sie sind keine individuelle Aussage darüber, ob ein Produkt für eine bestimmte Person gesundheitlich geeignet ist.")
    +P("Der kostenlose Bereich ist ohne Zahlungspflicht nutzbar. Premium bietet zusätzliche Funktionen, insbesondere detaillierte Bewertungsinformationen, Auswertungen zur Nährstoffversorgung, erweiterte Tagebuchfunktionen, Ernährungs- und Trainingsplanung sowie eigene Rezepte.")
    +P("Der für deinen Vertrag maßgebliche Funktionsumfang einschließlich etwaiger Nutzungsgrenzen wird vor der Bestellung angezeigt und mit der Vertragsbestätigung dokumentiert.")
    +P("Premium ist eine digitale Dienstleistung im Sinne der §§ 327 ff. BGB. Zur Nutzung sind ein kompatibles Gerät und eine Internetverbindung erforderlich; weitere technische Voraussetzungen werden vor Vertragsschluss angegeben.")
    +P("Ein bestimmter gesundheitlicher, sportlicher oder gewichtsbezogener Erfolg wird nicht geschuldet.")
    +H("§ 4 Vertragsschluss")
    +P("Die Darstellung von Premium auf unserer Website ist eine Aufforderung zur Abgabe einer Bestellung.")
    +P("Vor der verbindlichen Bestellung werden dir die wesentlichen Leistungen, der gewählte Tarif, der Gesamtpreis je Abrechnungszeitraum, die Testphase sowie Laufzeit und Kündigungsbedingungen angezeigt. Du kannst deine Angaben vor dem Absenden prüfen und berichtigen.")
    +P("Mit Betätigung der abschließenden, eindeutig auf die Zahlungspflicht hinweisenden Bestellschaltfläche gibst du ein verbindliches Vertragsangebot ab. Die Zahlungsabwicklung erfolgt über Stripe. Eine bloße Weiterleitung zu Stripe stellt noch keinen Vertragsschluss dar.")
    +P("Wir nehmen dein Angebot durch eine ausdrückliche Vertragsbestätigung per E-Mail oder durch Freischaltung von Premium an. Du erhältst die Vertragsbestätigung einschließlich dieser AGB und der Widerrufsbelehrung per E-Mail spätestens vor Beginn der Leistung.")
    +P("Vertragssprache ist Deutsch.")
    +H("§ 5 Kostenlose Testphase")
    +P("Bei erstmaligem Abschluss eines Premium-Abonnements erhältst du eine kostenlose Testphase von sieben Tagen. Sie beginnt mit der Freischaltung von Premium.")
    +P("Der genaue Zeitpunkt des Testendes und der ersten kostenpflichtigen Abrechnung wird dir vor der verbindlichen Bestellung angezeigt und mit der Vertragsbestätigung mitgeteilt.")
    +P("Du kannst das Abonnement bis zum Ende der Testphase kündigen. In diesem Fall endet Premium spätestens mit Ablauf der Testphase; es entstehen keine Abonnementkosten.")
    +P("Ohne rechtzeitige Kündigung beginnt unmittelbar anschließend die erste kostenpflichtige Laufzeit des gewählten Tarifs.")
    +P("Dein gesetzliches Widerrufsrecht besteht unabhängig von der Testphase und der Kündigungsmöglichkeit.")
    +H("§ 6 Preise und Zahlung")
    +P("Für Premium gelten folgende Preise:")
    +'<table style="border-collapse:collapse;width:100%;font-size:13px;margin:.4em 0"><tr><th style="border:1px solid var(--line);padding:5px 7px;text-align:left">Tarif</th><th style="border:1px solid var(--line);padding:5px 7px;text-align:left">Erste kostenpflichtige Laufzeit</th><th style="border:1px solid var(--line);padding:5px 7px;text-align:left">Gesamtpreis je Abrechnungszeitraum</th></tr><tr><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Monatlich</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Ein Monat</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">4,99 €</td></tr><tr><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Vierteljährlich</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Drei Monate</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">12,99 €</td></tr><tr><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Jährlich</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">Zwölf Monate</td><td style="border:1px solid var(--line);padding:5px 7px;text-align:left">44,99 €</td></tr></table>'
    +P("Alle genannten Preise sind Endpreise. Die Umsätze sind gemäß § 19 UStG von der Umsatzsteuer befreit; Umsatzsteuer wird nicht gesondert ausgewiesen.")
    +P("Die Zahlung erfolgt über die im Bestellvorgang angebotenen Zahlungsmittel von Stripe. Der jeweilige Gesamtbetrag wird nach Ende der kostenlosen Testphase und anschließend zu Beginn jedes weiteren Abrechnungszeitraums im Voraus fällig.")
    +P("Der bei Vertragsschluss vereinbarte Preis gilt auch während einer anschließenden unbefristeten Fortsetzung. Diese AGB begründen kein Recht zur einseitigen Preiserhöhung.")
    +H("§ 7 Laufzeit und Kündigung")
    +P("Während der kostenlosen Testphase gilt § 5.")
    +P("Die erste kostenpflichtige Laufzeit beträgt je nach gewähltem Tarif einen, drei oder zwölf Monate. Du kannst das Abonnement jederzeit mit Wirkung zum Ende dieser ersten Laufzeit kündigen; eine zusätzliche Kündigungsfrist ist dafür nicht erforderlich.")
    +P("Wird das Abonnement nicht gekündigt, läuft es anschließend <b>auf unbestimmte Zeit</b> weiter. Ab diesem Zeitpunkt kannst du es jederzeit <b>mit einer Frist von einem Monat</b> kündigen. Eine erneute Bindung für drei oder zwölf Monate entsteht nicht.")
    +P("Der gewählte Abrechnungsrhythmus bleibt bestehen. Endet der Vertrag innerhalb eines bereits bezahlten Abrechnungszeitraums, erstatten wir den auf die Zeit nach Vertragsende entfallenden Betrag tagegenau innerhalb von 14 Tagen.")
    +P("Die Kündigung ist über die auf unserer Website bereitgestellte Kündigungsfunktion oder per E-Mail an kontakt@root-index.de möglich. Zusätzlich kann die angebotene Abonnementverwaltung genutzt werden. Für eine ordentliche Kündigung ist keine Begründung erforderlich.")
    +P("Bei Nutzung der Kündigungsfunktion erhältst du unverzüglich eine elektronische Bestätigung mit dem Inhalt deiner Erklärung und dem Beendigungszeitpunkt.")
    +P("Das Recht zur außerordentlichen Kündigung aus wichtigem Grund bleibt für beide Seiten unberührt.")
    +P("Mit dem Ende des Premium-Abonnements entfallen die kostenpflichtigen Funktionen. Dein kostenloses Nutzerkonto bleibt bestehen, sofern du es nicht gesondert löschst.")
    +H("§ 8 Widerrufsrecht")
    +P("Verbrauchern steht grundsätzlich ein gesetzliches Widerrufsrecht von 14 Tagen ab Vertragsschluss zu. Einzelheiten ergeben sich aus der gesonderten Widerrufsbelehrung und dem Muster-Widerrufsformular, die vor Vertragsschluss bereitgestellt werden.")
    +P("Ein Widerruf kann insbesondere per E-Mail an kontakt@root-index.de oder über die elektronische Widerrufsfunktion auf unserer Website erklärt werden.")
    +P("Die vorzeitige Freischaltung von Premium und die Nutzung der kostenlosen Testphase führen nicht allein zum Erlöschen des Widerrufsrechts.")
    +P("Ein Leistungsbeginn vor Ablauf der Widerrufsfrist erfolgt auf dein ausdrückliches Verlangen. Ein etwaiger Wertersatz richtet sich ausschließlich nach den gesetzlichen Voraussetzungen; für die ausdrücklich kostenlose Testphase fällt kein Entgelt an.")
    +H("§ 9 Bereitstellung, Mängelrechte und Änderungen")
    +P("Wir stellen Premium während der Vertragslaufzeit im vereinbarten Umfang bereit. Die gesetzlich erforderlichen Aktualisierungen, einschließlich Sicherheitsaktualisierungen, werden bereitgestellt; über erforderliche Mitwirkung wirst du informiert.")
    +P("Vorübergehende Unterbrechungen können insbesondere durch notwendige Wartung oder technische Störungen entstehen. Planbare Wartungen werden nach Möglichkeit angekündigt und so durchgeführt, dass Beeinträchtigungen gering bleiben. Deine gesetzlichen Rechte bei Leistungsstörungen bleiben unberührt.")
    +P("Für Mängel gelten die gesetzlichen Vorschriften, insbesondere die §§ 327 ff. BGB.")
    +P("Über die zur Erhaltung der Vertragsmäßigkeit erforderlichen Aktualisierungen hinaus dürfen wir Premium ändern, wenn dies erforderlich ist, um die Anwendung an geänderte technische Umgebungen, neue gesetzliche Anforderungen oder nachweisbare Sicherheitsrisiken anzupassen. Änderungen müssen auf das hierfür erforderliche Maß begrenzt sein und dürfen keine zusätzlichen Kosten verursachen.")
    +P("Über solche Änderungen informieren wir dich klar und verständlich. Wird der Zugang oder die Nutzbarkeit mehr als nur unerheblich beeinträchtigt, informieren wir dich rechtzeitig vorab auf einem dauerhaften Datenträger, beispielsweise per E-Mail, über Inhalt, Zeitpunkt und deine Rechte.")
    +P("In diesem Fall kannst du den Vertrag nach Maßgabe des § 327r BGB innerhalb von 30 Tagen kostenfrei beenden. Die Frist beginnt mit Zugang der Information, frühestens jedoch mit der Änderung. Dieses Beendigungsrecht entfällt, wenn dir die unveränderte Leistung ohne zusätzliche Kosten erhalten bleibt.")
    +H("§ 10 Gesundheitshinweise und Haftung")
    +P("Bewertungen, Bedarfsberechnungen sowie Ernährungs- und Trainingsinformationen dienen der allgemeinen Information und Orientierung. Sie ersetzen keine ärztliche, pharmazeutische oder ernährungstherapeutische Beratung, Diagnose oder Behandlung.")
    +P("Berechnete Bedarfswerte beruhen auf Modellen und deinen Eingaben; der tatsächliche individuelle Bedarf kann davon abweichen. Bei Erkrankungen, Schwangerschaft, Unverträglichkeiten oder anderen besonderen gesundheitlichen Umständen sollten Änderungen an Ernährung, Supplementierung oder Training mit entsprechend qualifizierten Fachpersonen abgestimmt werden.")
    +P("Bei Allergien oder Unverträglichkeiten beachte zusätzlich die aktuelle Produktverpackung, da Hersteller Zusammensetzungen ändern können. Diese Hinweise beschränken nicht unsere vertraglichen Pflichten oder deine gesetzlichen Rechte.")
    +P("Wir haften unbeschränkt bei Vorsatz und grober Fahrlässigkeit sowie bei schuldhafter Verletzung von Leben, Körper oder Gesundheit.")
    +P("Bei einfacher Fahrlässigkeit haften wir bei Verletzung wesentlicher Vertragspflichten. Das sind Pflichten, deren Erfüllung die ordnungsgemäße Durchführung des Vertrags erst ermöglicht und auf deren Einhaltung du regelmäßig vertrauen darfst. Die Haftung ist dabei auf den vertragstypischen, bei Vertragsschluss vorhersehbaren Schaden begrenzt. Im Übrigen ist die Haftung für einfache Fahrlässigkeit ausgeschlossen.")
    +P("Die Haftung nach zwingenden gesetzlichen Vorschriften, insbesondere dem Produkthaftungsgesetz, sowie aufgrund ausdrücklich übernommener Garantien bleibt unberührt.")
    +P("Diese Regelungen gelten entsprechend für unsere gesetzlichen Vertreter und Personen, die wir zur Vertragserfüllung einsetzen.")
    +H("§ 11 Werbung und Partnerlinks")
    +P("Root Index kann gekennzeichnete Werbung und Partnerlinks enthalten. Bei einem Kauf über einen Partnerlink können wir eine Vergütung erhalten.")
    +P("Partnervergütungen haben keinen Einfluss auf die Produktbewertung. Eine positive Bewertung kann nicht gekauft werden.")
    +P("Kaufverträge über verlinkte Produkte kommen mit dem jeweiligen Händler zustande. Für diese Käufe gelten dessen Vertragsbedingungen.")
    +H("§ 12 Datenschutz")
    +P("Informationen zur Verarbeitung personenbezogener Daten findest du in der gesonderten Datenschutzerklärung.")
    +P("Soweit für die Verarbeitung bestimmter Daten, insbesondere Gesundheitsdaten, eine ausdrückliche Einwilligung erforderlich ist, wird diese gesondert eingeholt. Die Zustimmung zu diesen AGB ersetzt eine solche Einwilligung nicht.")
    +H("§ 13 Schlussbestimmungen")
    +P("Es gilt deutsches Recht unter Ausschluss des UN-Kaufrechts. Wenn du deinen gewöhnlichen Aufenthalt in einem anderen Staat hast, bleiben die zwingenden Verbraucherschutzvorschriften dieses Staates anwendbar, soweit sie dir Schutz gewähren, der dir durch die Rechtswahl nicht entzogen werden darf.")
    +P("Die gesetzlichen Gerichtsstände bleiben unberührt.")
    +P("Sollten einzelne Bestimmungen dieser AGB unwirksam sein, bleiben die übrigen Bestimmungen wirksam. An die Stelle unwirksamer Bestimmungen treten die gesetzlichen Regelungen.");
  const widerruf = H("Widerrufsbelehrung – Root Index Premium")
    +P("<i>Stand: September 2026</i>")
    +P("<button onclick=\"document.getElementById('legalOv').remove();riWiderrufFormular()\" style=\"margin:8px 0 4px;padding:10px 16px;border:0;border-radius:10px;background:var(--greendk);color:#fff;font-weight:700;cursor:pointer\">Vertrag widerrufen</button>")
    +H("Widerrufsrecht")
    +P("Du hast das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen.")
    +P("Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag des Vertragsschlusses.")
    +P("Um dein Widerrufsrecht auszuüben, musst du uns")
    +P("Ralph Denk – Root Index<br>Auweg 23<br>84103 Postau<br>Deutschland<br>E-Mail: <a href=\"mailto:kontakt@root-index.de\" style=\"color:var(--greendk)\">kontakt@root-index.de</a><br>Telefon: +49 160 94974290")
    +P("mittels einer eindeutigen Erklärung, beispielsweise per Brief oder E-Mail, über deinen Entschluss informieren, diesen Vertrag zu widerrufen.")
    +P("Du kannst dafür das beigefügte Muster-Widerrufsformular verwenden; vorgeschrieben ist das nicht.")
    +P("Du kannst dein Widerrufsrecht auch online über den Knopf <b>„Vertrag widerrufen“</b> ausüben – oben in dieser Widerrufsbelehrung, im Menü unter <b>Rechtliches → „Vertrag widerrufen“</b> oder direkt unter <b>root-index.de/?widerruf</b>. Wenn du diese Funktion nutzt, erhältst du unverzüglich eine Eingangsbestätigung per E-Mail mit dem Inhalt deiner Widerrufserklärung sowie dem Datum und der Uhrzeit ihres Eingangs.")
    +P("Zur Wahrung der Widerrufsfrist reicht es aus, dass du die Erklärung über die Ausübung des Widerrufsrechts vor Ablauf der Widerrufsfrist absendest.")
    +H("Folgen des Widerrufs")
    +P("Wenn du diesen Vertrag widerrufst, zahlen wir dir alle Zahlungen, die wir von dir erhalten haben, unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurück, an dem deine Widerrufserklärung bei uns eingegangen ist.")
    +P("Für die Rückzahlung verwenden wir dasselbe Zahlungsmittel, das du bei der ursprünglichen Zahlung eingesetzt hast, sofern mit dir nicht ausdrücklich etwas anderes vereinbart wurde. Wegen der Rückzahlung berechnen wir dir keine Entgelte.")
    +P("Hast du ausdrücklich verlangt, dass wir mit der Dienstleistung bereits während der Widerrufsfrist beginnen, ist unter den gesetzlichen Voraussetzungen ein angemessener Betrag für die bis zu deinem Widerruf erbrachte Leistung zu zahlen. Dieser entspricht dem Anteil der bereits erbrachten Leistung am vertraglich vereinbarten Gesamtumfang.")
    +P("Die vereinbarte siebentägige Testphase bleibt kostenlos. Für diesen Zeitraum berechnen wir auch im Fall eines Widerrufs keinen Wertersatz.")
    +H("Ergänzende Hinweise zur Testphase")
    +P("Die Widerrufsfrist beginnt mit dem Vertragsschluss, nicht erst mit der ersten kostenpflichtigen Abrechnung.")
    +P("Die Freischaltung und Nutzung von Root Index Premium führen allein nicht zum Erlöschen deines Widerrufsrechts.")
    +P("Die Kündigung während der kostenlosen Testphase und das gesetzliche Widerrufsrecht bestehen unabhängig voneinander. Laufzeit und Kündigung des Abonnements sind in den AGB geregelt.")
    +H("Muster-Widerrufsformular")
    +P("Wenn du den Vertrag widerrufen möchtest, kannst du dieses Formular ausfüllen und an uns senden. Die Verwendung ist freiwillig.")
    +P("An:<br>Ralph Denk – Root Index<br>Auweg 23<br>84103 Postau<br>Deutschland<br>E-Mail: <a href=\"mailto:kontakt@root-index.de\" style=\"color:var(--greendk)\">kontakt@root-index.de</a>")
    +P("Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über die Erbringung folgender Dienstleistung:<br><b>Root Index Premium</b>")
    +P("Bestellt am: ______________________________<br>Name des/der Verbraucher(s): ______________________________<br>Anschrift des/der Verbraucher(s): ______________________________<br>Unterschrift des/der Verbraucher(s) – nur bei Mitteilung auf Papier: ______________________________<br>Datum: ______________________________")
    +P("(*) Unzutreffendes streichen.")
    +P("<button onclick=\"document.getElementById('legalOv').remove();riWiderrufFormular()\" style=\"margin:8px 0 4px;padding:10px 16px;border:0;border-radius:10px;background:var(--greendk);color:#fff;font-weight:700;cursor:pointer\">Vertrag widerrufen</button>");
  const body = which==='datenschutz'?ds : which==='agb'?agb : which==='widerruf'?widerruf : impressum;
  ov.innerHTML=`<div style="background:var(--card);max-width:640px;width:92%;margin:24px 0;border-radius:16px;max-height:88vh;overflow:auto;padding:20px 22px;box-shadow:var(--shadow)"><button onclick="document.getElementById('legalOv').remove()" style="float:right;border:0;background:var(--line);color:var(--ink);width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px">×</button>${body}</div>`;
  document.body.appendChild(ov);
}
function wikiOpen(){
  let ov=document.getElementById("wikiOv"); if(ov) ov.remove();
  ov=document.createElement("div"); ov.id="wikiOv";
  ov.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;justify-content:center;z-index:80";
  ov.onclick=e=>{ if(e.target===ov) ov.remove(); };
  const H=(t)=>`<div style="font-size:12px;text-transform:uppercase;letter-spacing:.6px;color:var(--k-16a34a);font-weight:700;margin:18px 0 6px">${t}</div>`;
  const box=(inner)=>`<div style="background:var(--bg);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin-bottom:8px;font-size:13.5px;line-height:1.55;color:var(--ink)">${inner}</div>`;
  ov.innerHTML=`<div style="display:flex;flex-direction:column;width:100%;max-width:640px;height:100%;background:var(--card)">
    <div style="display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid var(--line);flex:0 0 auto"><b style="font-size:17px">📖 So funktioniert Root Index</b><button onclick="document.getElementById('wikiOv').remove()" style="border:0;background:var(--k-eef3ef);border-radius:8px;padding:7px 12px;cursor:pointer;font-size:14px">Schließen ✕</button></div>
    <div style="flex:1;overflow:auto;padding:12px 16px 28px">
      <p style="font-size:13.5px;color:var(--muted);line-height:1.5">Transparent, wissenschaftsbasiert, nachvollziehbar. Hier steht, wie der <b>Root Index</b> und der <b>Kalorienrechner</b> rechnen – inklusive der Sonderfälle.</p>
      ${methodikAn()?`<div style="margin:10px 0 2px"><span onclick="document.getElementById('wikiOv').remove();methodikGo('mdSekAchsen')" role="link" tabindex="0" style="cursor:pointer;display:inline-flex;align-items:center;gap:5px;font-size:12.5px;color:var(--k-16a34a);font-weight:600;border-bottom:1px dotted var(--line);padding-bottom:1px">🧭 Kurzfassung: Unsere Methode <span style="opacity:.6">›</span></span></div>`:``}

      ${H("Root Index (0–100)")}
      ${box(`Setzt sich aus vier Teilen zusammen:<br>
        • <b>Zutatenqualität</b> (max 30) – Ø der Bewertungen aller Zutaten, nach Gewicht.<br>
        • <b>Zusatzstoffe</b> (max 15) – keine = beste Wertung; künstliche Süßstoffe/Zusätze mindern.<br>
        • <b>Verarbeitung</b> (max 15) – wie stark ein Lebensmittel verarbeitet ist (nach der NOVA-Klassifikation); unverarbeitet/Vollwert am besten.<br>
        • <b>Nährwertqualität</b> (max 40) – gutes Makro-Profil pro 100 g (Eiweiß/Ballaststoffe hoch, Zucker/gesättigtes Fett/Salz niedrig, Kohlenhydrate, die den Blutzucker nur langsam steigen lassen).<br>
        <b>Einstufung:</b> ≥ 90 Sehr gut · ≥ 75 Gut · ≥ 60 Mittel · sonst Schwach.<br>
        <b>Alkohol</b> (Ethanol, IARC-Gruppe 1) deckelt die Wertung auf höchstens „Gut".`)}

      ${H("Sonderregeln")}
      ${box(`<b>Öle &amp; Fette:</b> Statt des Makro-Profils zählt die <b>Fettqualität</b> – der Anteil ungesättigter Fettsäuren. So schneiden z. B. Oliven-, Lein- und Nussöle hoch ab, stark gesättigte Fette (Talg, Butterschmalz) niedriger. Öl nutzt man in kleinen Mengen, nicht pro 100 g.`)}
      ${box(`<b>Süßungsmittel und Salze</b> bekommen <b>gar keinen</b> Index. Ein Süßungsmittel besteht aus dem, was der Index abwerten würde, und Salz hat weder Nährwertprofil noch Zutatenliste – eine Punktzahl wäre dort keine Messung. Bei <b>0‑kcal-Produkten</b> wie Essig ist der Nährwert-Teil nicht sinnvoll und <b>entfällt</b>; bewertet werden dann Zutaten, Verarbeitung &amp; Zusatzstoffe.`)}
      ${box(`<b>Supplements bekommen keinen Index</b>, sondern einen <b>Dosis-Check</b>: eine Ampel je Wirkstoff gegen die EFSA-Referenzwerte. Eine Kapsel hat kein Nährwertprofil, und drei von vier Achsen sind bei Präparaten praktisch überall gleich – eine Summe daraus sähe genau aus und wüsste fast nichts. <b>Ausnahme Proteinpulver:</b> Da man es in Mahlzeiten-Mengen isst (nicht mikro-dosiert wie eine Vitaminkapsel), zählt die Nährwert-Achse wie bei einem Lebensmittel – es bekommt daher einen normalen Index.<br><br>
        <b>Trägerstoffe der Darreichung</b> – Kapselhülle (Gelatine, Cellulose/HPMC, Pullulan) und das Feuchthaltemittel Glycerin (E422) – werden bei Supplements <b>nicht als Verarbeitungs- oder Zutaten-Malus</b> gewertet: Sie sind pharmakopöe-/EU-zugelassen und gesundheitlich inert und machen ein Präparat nicht ungesünder. Bewertet wird der <b>Wirkstoff</b> (Form, Dosis, Reinheit). So wird eine Kapsel nicht wie ein hochverarbeitetes Lebensmittel behandelt. Ebenfalls inert und daher nicht abgewertet: <b>Magnesiumstearat (E470b)</b> und <b>mikrokristalline Cellulose (E460)</b> – EFSA-Neubewertungen 2018 ohne Sicherheitsbedenken. <b>Nicht</b> ausgenommen bleiben Siliciumdioxid (E551), Maltodextrin und Methylcellulose. <b>Titandioxid (E171)</b> zählt dagegen als Negativpunkt (EFSA 2021: nicht mehr sicher, EU-Verbot seit 2022). Grundlagen: EU-VO 1333/2008, EFSA-Bewertungen, Europäisches Arzneibuch.`)}

      ${H("Süßstoffe, Zuckeralkohole & schnelle Kohlenhydrate")}
      ${box(`Wie eine Zutat eingestuft wird, richtet sich nach ihrem <b>Verarbeitungsgrad</b> – nicht nach „gesund/ungesund“ (das steckt im Nährwert- und Zusatzstoff-Teil). Für Süßes heißt das:<br><br>
        • <b>Künstliche Süßstoffe</b> (Sucralose, Aspartam, Acesulfam) sind vollsynthetische Stoffe – sie stehen so niedrig wie Zucker, <b>nicht besser</b>. Die WHO rät (2023) davon ab, sie als Zucker-Ersatz zur Gewichtskontrolle zu nutzen.<br>
        • <b>Natürliche Süßstoffe</b> (Steviolglycoside/Stevia) stehen einen Tick höher – pflanzlich, ohne die spezifischen Warnsignale. Aber „natürlich“ ist <b>kein Freifahrtschein</b>: die WHO zählt auch Stevia dazu.<br>
        • <b>Zuckeralkohole</b> (Erythrit, Xylit) liegen darüber: Sie erhöhen den Blutzucker kaum und sind zahnfreundlich – ein Lebensmittel sind sie trotzdem nicht.`)}
      ${box(`<b>Der versteckte Schnellzucker.</b> Manche Zutaten treiben den Blutzucker <b>so stark wie Zucker oder stärker</b>, tauchen auf dem Etikett aber nicht als „Zucker“ auf, sondern als Stärke: <b>Maltodextrin, Traubenzucker (Dextrose), Glukose- und Reissirup</b>. Wir bewerten sie deshalb <b>auf Zucker-Niveau</b>.<br><br>
        Ganze Lebensmittel strafen wir dafür <b>nicht</b> ab: <b>Datteln</b> und <b>Honig</b> enthalten zwar Zucker, verlaufen durch Ballaststoffe bzw. geringe Verarbeitung aber deutlich sanfter als reiner Traubenzucker – das bilden schon der Verarbeitungs- und der Nährwert-Teil ab.`)}

      ${box(`<b>Blutzucker (seit 25.09.2026).</b> Nicht nur Zucker lässt den Blutzucker steigen – auch Stärke aus Reis, Mais oder Weißmehl geht schnell ins Blut. Wir schauen deshalb, <b>wie viele Kohlenhydrate auf ein Gramm Ballaststoffe</b> kommen:<br>
        • höchstens <b>5 g</b> → volle Punkte (z. B. Kichererbsen, Knäckebrot)<br>
        • höchstens <b>10 g</b> → halbe Punkte (z. B. Haferflocken, Vollkornbrot)<br>
        • mehr → keine Punkte (z. B. Reiswaffeln, Cornflakes, weißer Reis)<br>
        <b>Eiweißreiche</b> Produkte (ab 6 g Eiweiß je 100 kcal, z. B. Linsen) rücken eine Stufe besser – Eiweiß bremst den Anstieg. Bei sehr wenig Kohlenhydraten (höchstens 5 g je 100 g, z. B. Käse, Fleisch, Milch) zählt dieser Teil nicht. Er ist einer von sechs Teilen der Nährwertqualität; die Achse bleibt bei 40 Punkten.<br>
        <i>Grenze: Ob Getreide gepufft oder gemahlen ist, steht nicht auf dem Etikett – den echten glykämischen Index gibt es nur aus Messtabellen, und den nutzen wir bewusst nicht.</i>`)}

      ${H("Zusatzstoffe – wissenschaftlich bewertet")}
      ${box(`Die Zusatzstoff-Wertung misst die <b>gesundheitliche Bedenklichkeit</b> – nicht den Verarbeitungsgrad (den zeigt die Achse „Verarbeitung“). Grundlage: <b>EU-Verordnung (EG) Nr. 1333/2008</b> und <b>EFSA</b>-Bewertungen. Wir prüfen die Studienlage regelmäßig.<br><br>
        <b>Als unbedenklich gewertet</b> (EU-zugelassen, EFSA ohne Sicherheitsbedenken – ADI „not specified“): z. B. Guarkernmehl (E412), Johannisbrotkernmehl (E410), Pektin (E440), Ascorbinsäure/Vitamin C (E300), Tofu-Gerinnungsmittel (E509/E511/E516), natürliche Aromen &amp; Rosmarinextrakt.<br><br>
        <b>Abgewertet</b> (Hinweise auf Effekte an Darmbarriere/Mikrobiom oder Gesundheit): Carrageen (E407), Carboxymethylcellulose (E466), Polysorbat 80 (E433/E435), Nitritpökelsalz (E250).<br><br>
        <b>Süßstoffe:</b> künstliche (z. B. Sucralose, Acesulfam-K) mindern stärker als natürliche (Stevia).<br><br>
        <i>Ein Produkt gilt nur dann als „ohne Zusatzstoffe“, wenn <b>alle</b> enthaltenen Zusätze unbedenklich sind. Ist auch nur einer abgewertet, zählt das Produkt als „mit Zusatzstoffen“. Keine medizinische Beratung.</i>`)}

      ${H("Kalorien- & Bedarfsrechner")}
      ${box(`<b>Grundumsatz (BMR)</b> – Genauigkeit von oben nach unten:<br>
        1. <b>Gemessen</b> (InBody/DEXA) – wird direkt genutzt, wenn eingetragen.<br>
        2. <b>Katch-McArdle</b> – wenn <b>Körperfett %</b> bekannt: 370 + 21,6 × fettfreie Masse. Am besten für schlanke/muskulöse Personen.<br>
        3. <b>Mifflin-St-Jeor</b> – Standard aus Alter/Geschlecht/Größe/Gewicht.<br>
        Körperfett schätzen ohne Gerät: <b>U.S.-Navy-Maßband</b> (Hals, Taille, bei Frauen Hüfte, + Größe), ±3–4 %.`)}
      ${box(`<b>Erhaltungsbedarf</b> = Grundumsatz × Aktivitätsfaktor.<br>
        <b>Ziel-Energie</b> = Erhaltungsbedarf ± gewähltes Tempo.<br>
        🔒 <b>Nie unter den Grundumsatz</b>: dauerhaft darunter zu essen ist ungesund (Muskelabbau, Energie/Hormone) – der Rechner sperrt das.`)}
      ${box(`<b>Makro-Verteilung</b> (nach DGE-Richtwerten):<br>
        • <b>Eiweiß:</b> aus g/kg (Richtwert 1,5–2 g/kg; Bezug Ziel- oder aktuelles Gewicht; bei Übergewicht eher Zielgewicht/fettfreie Masse).<br>
        • <b>Fett:</b> DGE-Richtwert ~30 En% (25–35 % wählbar).<br>
        • <b>Kohlenhydrate:</b> der Rest – entspricht der DGE-Logik (KH ergeben sich aus Energiebedarf, Eiweiß- und Fett-Richtwert; Mischkost > 50 En%).`)}
      ${box(`<b>Alle 3–4 Wochen abgleichen:</b> wiegen, ggf. Körperfett neu messen, mit dem getrackten Essen vergleichen und den Bedarf am echten Gewichtsverlauf feinjustieren. Jede Formel ist nur eine Schätzung (±5–10 %).`)}

      ${H("Fette &amp; Frauen (Zyklus)")}
      ${box(`Es gibt <b>keinen</b> Beleg, dass Frauen <i>mehr</i> Fett brauchen als Männer. Was die Studien stützen: <b>genug</b> Fett (nicht extrem fettarm) und vor allem die <b>Fettqualität</b> – überwiegend <b>ungesättigt, besonders Omega-3</b>.<br>
        • Sehr fettarme Kost (20–25 En%) senkte in kontrollierten Studien messbar Sexualhormone (u. a. Östron, Testosteron, SHBG).<br>
        • Mehrfach ungesättigte Fette (PUFA) waren mit <b>geringerem Risiko für ausbleibenden Eisprung</b> verbunden.<br>
        • <b>Omega-3 (EPA/DHA)</b> trägt ab <b>250 mg/Tag</b> zur <b>normalen Herzfunktion</b> bei (zugelassene EU-Angabe).<br>
        <b>Quellen:</b> fetter Fisch (Lachs, Hering, Makrele), Lein-/Rapsöl, Walnüsse.<br>
        <i>Hinweis: allgemeine Information, keine medizinische Beratung – bei starken Beschwerden ärztlich abklären.</i>`)}

      ${H("Was ist PMS?")}
      ${box(`<b>PMS</b> (prämenstruelles Syndrom) sind Beschwerden, die <b>ein paar Tage vor der Periode</b> beginnen und <b>mit dem Einsetzen der Blutung wieder verschwinden</b>.<br>
        • <b>Körperlich:</b> Bauch-/Rückenschmerzen, Brustspannen, Völlegefühl, Kopfschmerzen, Heißhunger.<br>
        • <b>Stimmung:</b> Reizbarkeit, Stimmungsschwankungen, innere Unruhe, Müdigkeit.<br>
        Sehr verbreitet: Die meisten Frauen kennen leichte Formen; bei wenigen ist es so stark, dass es den Alltag stört (dann spricht man von <b>PMDS</b>).<br>
        <i>Unterschied zu Regelschmerzen: PMS kommt <b>vor</b> der Blutung, Regelschmerzen treten <b>während</b> der Blutung auf. Keine medizinische Beratung.</i>`)}

      ${H("Zyklus &amp; Nährstoffe – was zugelassen ist")}
      ${box(`Root Index macht <b>keine Aussagen zu Beschwerden</b>. Nach der EU-Health-Claims-Verordnung (EG 1924/2006) dürfen Lebensmittel und Nahrungsergänzungsmittel nur mit <b>zugelassenen</b> Angaben beworben werden – Aussagen zur Linderung von Krankheiten oder Symptomen sind ausdrücklich verboten. Was <b>erlaubt</b> ist, sind Angaben zur normalen Körperfunktion:<br>
        • <b>Magnesium</b> – „trägt zu einer <b>normalen Muskelfunktion</b> bei" und „zur <b>Verringerung von Müdigkeit und Ermüdung</b>". <b>200–300 mg/Tag</b> (Form „Bisglycinat" = magenschonend).<br>
        • <b>Vitamin B6</b> – „trägt zur <b>Regulierung der Hormontätigkeit</b> bei".<br>
        • <b>Vitamin B1</b> (Thiamin) – „trägt zu einem <b>normalen Energiestoffwechsel</b> bei" und „zur <b>normalen Funktion des Nervensystems</b>".<br>
        • <b>Omega-3 (EPA/DHA)</b> – „tragen zur <b>normalen Herzfunktion</b> bei" (ab <b>250 mg/Tag</b>).<br>
        • <b>Eisen</b> – „trägt zur <b>Verringerung von Müdigkeit und Ermüdung</b> bei". Eisenpräparate nur bei <b>ärztlich bestätigtem Mangel</b> (Blutbild) – eine Überdosierung ist schädlich. <b>⚠️ Unbedingt ärztlich abklären.</b><br>
        • <b>Mönchspfeffer/Vitex</b> – ein Pflanzenextrakt. Für Botanicals ist in der EU derzeit <b>keine</b> Angabe zugelassen; wir behaupten deshalb keine Wirkung. Er wirkt auf den Hormonhaushalt → bei Kinderwunsch oder Medikamenten <b>ärztlich abklären</b>.<br>
        <b>Sauber statt Kombi-Pulver:</b> lieber wenige saubere Einzel-Produkte (je 1 Wirkstoff, ohne Farbe/Aroma) als ein additivreiches All-in-one.<br>
        <i>Quelle: EU-Register zugelassener Angaben (VO 432/2012). Allgemeine Information, keine medizinische Beratung. Bei Beschwerden bitte ärztlich abklären.</i>`)}

      <p style="font-size:11.5px;color:var(--k-9aa7a0);margin-top:16px">Quellen u. a. DGE/D-A-CH-Referenzwerte sowie peer-reviewte Studien zu Fett/Hormonen und Omega-3/Dysmenorrhoe. Dies ist keine medizinische Beratung.</p>
    </div></div>`;
  document.body.appendChild(ov);
}
