  if(bm&&bc){ const on2='background:var(--green);color:var(--auf-gruen)', off2='background:var(--card);color:var(--ink)';
    bm.style.cssText="padding:7px 11px;border:0;cursor:pointer;font-size:13px;"+(_planMode!=='kalender'?on2:off2);
    bc.style.cssText="padding:7px 11px;border:0;border-left:1px solid var(--line);cursor:pointer;font-size:13px;"+(_planMode==='kalender'?on2:off2); }
  if(_planMode==='kalender'){ await renderKalenderGrid(dates); return; }
  let entries=[]; try{ const {data}=await client.rpc("cb_plan_woche",{p_von:von,p_bis:bis}); entries=data||[]; }catch(e){}
