async function saveRezept(){
  const msg=document.getElementById("rzfMsg"); msg.style.color="var(--k-dc2626)";
  const name=(document.getElementById("rzfName").value||"").trim();
  if(!name){ msg.textContent="Bitte einen Namen angeben."; return; }
  const zut=[];
  document.querySelectorAll("#rzfZutaten .rzZ").forEach(row=>{
    const pid=(row.querySelector(".rzZpid").value||"").trim();
    let n;
    if(pid){ const pr=(ALL||[]).find(x=>x.id===pid); n=pr?prodLabel(pr):""; }
    else { n=(row.querySelector(".rzZName").value||"").trim(); }
    if(!n) return;
    const amt=parseFloat(row.querySelector(".rzZg").value);
    const unit=(row.querySelector(".rzZu")||{}).value||"g";
    const grams=rzToGrams(amt,unit,pid);
    const disp=(amt>0)?(String(amt).replace(/\.0$/,"")+" "+unit):null;
    zut.push({name:n, menge_g:(grams!=null?Math.round(grams*10)/10:null), menge:disp, produkt_id:pid||null});
  });
  const v=id=>{const e=document.getElementById(id);return e&&e.value!==""?e.value:null;};
  const mahlzeiten=[...document.querySelectorAll(".rzfMeal:checked")].map(x=>x.value);
  const editId=(document.getElementById("rzfEditId")||{}).value||null;
  const payload={name, portionen:v("rzfPort"), zeit:v("rzfZeit"), ziel:v("rzfZiel"),
    ernaehrungsform:v("rzfEf"), kcal:v("rzfKcal"), protein:v("rzfP"), kh:v("rzfKh"), fett:v("rzfF"),
    zubereitung:(document.getElementById("rzfPrep").value||""), zutaten:zut, mahlzeiten, rezept_id:editId};
  msg.style.color="var(--k-6b7280)"; msg.textContent=editId?"Aktualisiere…":"Speichere…";
  const {data:rid,error}=await client.rpc("cb_rezept_anlegen",{p_payload:payload});
  if(error){ msg.style.color="var(--k-dc2626)"; msg.textContent="Fehler: "+error.message; return; }
  const fileEl=document.getElementById("rzfBild"), file=fileEl&&fileEl.files&&fileEl.files[0];
  if(file && rid){
    try{
      msg.textContent="Lade Foto hoch…";
      const ext=((file.name.split(".").pop()||"jpg").toLowerCase()).replace(/[^a-z0-9]/g,"")||"jpg";
      const path=rid+"."+ext;
      const up=await client.storage.from("rezeptbilder").upload(path,file,{upsert:true,contentType:file.type||"image/jpeg"});
      if(!up.error){ const {data:pu}=client.storage.from("rezeptbilder").getPublicUrl(path);
        if(pu&&pu.publicUrl) await client.rpc("cb_rezept_setbild",{p_rezept:rid,p_url:pu.publicUrl}); }
    }catch(e){ /* Rezept ist gespeichert, Foto optional */ }
  }
  closeP();
  REZEPTE=null; await loadRezepte();
}
async function publishRezept(id, pub){
  if(!pub && !confirm("Rezept wieder auf privat setzen? Andere sehen es dann nicht mehr.")) return;
  const {error}=await client.rpc("cb_rezept_publish",{p_rezept:id, p_public:pub});
  if(error){ alert("Fehler: "+error.message); return; }
  closeP(); REZEPTE=null; await loadRezepte();
}
async function deleteRezept(id){
  if(!confirm("Dieses Rezept endgültig löschen?")) return;
  const {error}=await client.rpc("cb_rezept_delete",{p_rezept:id});
  if(error){ alert("Fehler: "+error.message); return; }
  closeP(); REZEPTE=null; await loadRezepte();
}
