/* Liest eine GANZE Stueckzahl aus der Mengenangabe: "180 g (3 St.)" -> {anzahl:3, wort:"St."}
   Bewusst eng gefasst - es wird nur erkannt, was zweifelsfrei stueckig ist:
     erkannt:       (3 St.) · (11 St.) · (3 Scheiben) · 2 Stück
     nicht erkannt: (½ St.) · (1/3 St.) · (1½ Dose) · 1–2 EL · 1 Prise
   Bruchteile bleiben absichtlich draussen: eine halbe Paprika ist eine normale
   Menge, und auf ganze Stueck zu runden wuerde sie verdoppeln oder streichen. */
function stueckAnteil(txt){
  const s=String(txt||"");
  if(/[½¼¾⅓⅔⅛]|\d\s*\/\s*\d|[–-]\s*\d/.test(s)) return null;   // Brueche und Bereiche raus
  /* Reihenfolge zaehlt: die laengste Schreibweise zuerst, sonst schnappt sich "St."
     das Wort "Stück" und in der Anzeige stuende "3 St" statt "3 Stück". */
  let m = s.match(/\((\d+)\s*(Stück|Stueck|Scheiben|Scheibe|Riegel|Eier|St\.?|Ei)\)/i);
  if(!m) m = s.match(/^(\d+)\s*(Stück|Stueck|Scheiben|Scheibe|Riegel|Eier|St\.?|Ei)\b/i);
  if(!m) return null;
  const n=parseInt(m[1],10);
  if(!isFinite(n)||n<1) return null;
  return {anzahl:n, wort:m[2]};
}
function renderRezeptScaled(){
  const r=_rezept; if(!r) return;
  const z=Array.isArray(r.zutaten)?r.zutaten:[];
  const pro = ME && hasFeat('rezepte_pro');
  const P0=num(r.portionen)||1, K0=num(r.kcal)||0, rd=x=>Math.round(x);
  let pers=P0, zielK=null, train=false;
  if(pro){
    const pe=document.getElementById("rzPers"), ke=document.getElementById("rzKcal"), te=document.getElementById("rzTrain");
    pers=parseFloat(pe&&pe.value)||P0;
    const zk=parseFloat(ke&&ke.value); zielK=isNaN(zk)?null:zk;
    train=!!(te&&te.checked);
  }
  const fK = (zielK && K0) ? zielK/K0 : 1;       // Portionsgröße (Ziel-kcal)
  const totalFactor = fK * (pers/P0);            // Gesamtmenge der Zutaten
  const zHtml=z.map(i=>{
    const sc=num(i.clean_score);
    const badge = sc!=null ? `<span style="font-size:11px;font-weight:700;color:var(--k-ffffff);background:${farbe(i.bewertung)};border-radius:6px;padding:1px 6px;margin-left:6px">${sc}</span>` : "";
    let mengeStr; const g=num(i.menge_g);
    /* Stueckige Zutaten springen, sie kriechen nicht. Ralph, 18.07.2026:
       "es bleibt 1 Ei oder 1 Knaeckebrot, bis die Skalierung dazu passt."
       Aus "180 g (3 St.)" wird bei Faktor 1,1 wieder 3 St. - erst ab 1,5 werden es 4.
       Halbe und Viertel ("½ St.", "1/3 St.") werden bewusst NICHT so behandelt:
       eine halbe Paprika ist eine normale Menge, da ist Runden auf ganze Stueck falsch. */
    const stk = stueckAnteil(i.menge);
    if(g!=null && stk){
      const proStueck = g/stk.anzahl;
      const neu = Math.max(1, Math.round(stk.anzahl*totalFactor));
      const gs = neu*proStueck;
      mengeStr = rd(gs)+" g <span style=\"color:var(--muted)\">("+neu+" "+esc(stk.wort)+")</span>"
        +(train?` · <span style="color:var(--k-b45309)">Trainingstag ${rd(gs*1.2)} g</span>`:"");
    }
    else if(g!=null){ const gs=g*totalFactor; mengeStr=rd(gs)+" g"+(train?` · <span style="color:var(--k-b45309)">Trainingstag ${rd(gs*1.2)} g</span>`:""); }
    else { mengeStr=esc(i.menge||"nach Geschmack"); }
    return `<div style="display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)"><span>${esc(i.name)}${badge}</span><span style="color:var(--muted);white-space:nowrap;text-align:right">${mengeStr}</span></div>`;
  }).join("");
  const zc=document.getElementById("rzZutaten"); if(zc) zc.innerHTML=zHtml;
  const kb=document.getElementById("rzKcalBadge"); if(kb) kb.textContent=K0?rd(K0*fK):"–";
  const pi=document.getElementById("rzPortInfo"); if(pi) pi.textContent=`${rd(pers)} Portion(en)`;
  const mk=document.getElementById("rzMakros");
  if(mk) mk.innerHTML=`Protein <b>${num(r.protein)!=null?rd(num(r.protein)*fK):"–"} g</b> · Kohlenhydrate <b>${num(r.kh)!=null?rd(num(r.kh)*fK):"–"} g</b> · Fett <b>${num(r.fett)!=null?rd(num(r.fett)*fK):"–"} g</b><div class="formula">pro Portion${(rd(pers)!=P0)?` · gesamt ${rd(pers)} Portion(en)`:""}</div>`;
  const bud=document.getElementById("rzBudget");
  if(bud){
    const nLog=parseFloat((document.getElementById("rzTbPort")||{}).value)||1;
    const tf=train?1.2:1, f2=fK*tf*nLog;
    const recK=K0?rd(K0*f2):0, recP=rd((num(r.protein)||0)*f2), recKh=rd((num(r.kh)||0)*f2), recF=rd((num(r.fett)||0)*f2);
    const eaten=rd(num((_daySum||{}).kcal)||0), eP=rd(num((_daySum||{}).protein)||0), eKh=rd(num((_daySum||{}).kh)||0), eF=rd(num((_daySum||{}).fett)||0);
    const gK=num((_goal||{}).Kalorienziel_kcal), gP=num((_goal||{}).Eiweiss_ziel_g), gKh=num((_goal||{}).KH_ziel_g), gF=num((_goal||{}).Fett_ziel_g);
    const row=(lbl,eat,goal,rec,u)=>{
      const r2=(u||''); const right = goal==null
        ? `<span style="color:var(--muted)">${eat}${r2} gegessen</span>`
        : `${eat}/${rd(goal)}${r2} · Rest <b style="color:${(goal-eat-rec)<0?'var(--k-dc2626)':'var(--k-16a34a)'}">${rd(goal-eat-rec)}${r2}</b>`;
      return `<div style="display:flex;justify-content:space-between;gap:12px;padding:3px 0;border-top:1px solid var(--k-dbeafe)"><span><b>${lbl}</b> <span style="color:var(--muted)">Rezept +${rec}${r2}</span></span><span style="text-align:right">${right}</span></div>`;
    };
    bud.innerHTML=`<div style="font-weight:700;margin-bottom:3px">Tagesbudget – Rest nach diesem Rezept</div>`
      + row('kcal',eaten,gK,recK,'')
      + row('Eiweiß',eP,gP,recP,' g')
      + row('KH',eKh,gKh,recKh,' g')
      + row('Fett',eF,gF,recF,' g')
      + (gK==null?`<div style="color:var(--muted);margin-top:4px">Tipp: Tagesziele in „Mein Profil" setzen, dann siehst du den Rest.</div>`:'');
  }
}
async function loadRezeptBudget(){
  try{
    const r1=await client.rpc("cb_tagessumme",{p_datum:tbToday()});
    const r2=await client.rpc("cb_profil");
    _daySum=(r1&&r1.data&&r1.data[0])||{}; _goal=(r2&&r2.data&&r2.data[0])||{};
  }catch(e){ _daySum=_daySum||{}; _goal=_goal||{}; }
  renderRezeptScaled();
}
/* ===== Work #770 (Ralph 19.09.2026): Zeiten fuer Mahlzeiten und Training =====
   "die zeiten fuer mahlzeiten soll man in mein profil definieren koennen,
    grundeistellung wuerde ich trotzdem setzen. trainigszeiten soll man auch
    einstellen koennen und dann im planer auch noch verschieben koennen."

   Die Grundeinstellung steht NICHT hier, sondern in cb_zeiten_standard auf dem
   Server. Zweimal geschrieben liefe sie irgendwann auseinander, und niemand
   wuesste, welche gilt. cb_zeiten_holen liefert immer einen Wert - entweder den
   eigenen oder den Standard -, deshalb muss die Oberflaeche nie entscheiden. */
function minToTime(m){ m=+m||0; return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'); }
function timeToMinSafe(s){ if(!s) return null; const p=String(s).split(':'); const m=(+p[0])*60+(+(p[1]||0)); return isFinite(m)?m:null; }
async function zeitenRender(){
  const box=document.getElementById("profZeiten"); if(!box) return;
  let liste=[];
  try{ const {data,error}=await client.rpc("cb_zeiten_holen"); if(error) throw error; liste=data||[]; }
  catch(e){ box.innerHTML='<div style="color:var(--k-dc2626);font-size:13px">Zeiten liessen sich nicht laden: '+esc(e.message||"unbekannt")+'</div>'; return; }
  box.innerHTML='<div style="font-weight:600;font-size:13px;margin-bottom:6px">Zeiten im Tagesablauf</div>'
    +'<div style="font-size:12px;color:var(--muted);margin-bottom:10px">Damit Mahlzeiten und Training im Kalender an der richtigen Stelle stehen. Leer lassen heißt: Grundeinstellung.</div>'
    +liste.map(function(z){
      return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;font-size:13px">'
        +'<span style="flex:1">'+esc(z.label)+'</span>'
        +'<input type="time" value="'+minToTime(z.start_min)+'" onchange="zeitSetzen(\''+esc(z.schluessel)+'\',this.value)" style="padding:6px;border:1px solid var(--line);border-radius:8px">'
        +(z.eigen?'<button onclick="zeitSetzen(\''+esc(z.schluessel)+'\',null)" title="Auf Grundeinstellung zurück" style="border:0;background:none;color:var(--muted);cursor:pointer;font-size:12px">↺</button>':'<span style="width:18px"></span>')
        +'</div>';
    }).join('')
    +'<div id="profZeitMsg" style="font-size:12px;margin-top:4px"></div>';
}
