async function addRezeptToTb(){
  const r=_rezept; if(!r) return; const msg=document.getElementById("rzTbMsg");
  const meal=(document.getElementById("rzMeal")||{}).value||"Snack";
  const pro=ME&&hasFeat('rezepte_pro'); const P0=num(r.portionen)||1, K0=num(r.kcal)||0;
  let fK=1; if(pro){ const zk=parseFloat((document.getElementById("rzKcal")||{}).value); if(!isNaN(zk)&&K0) fK=zk/K0; }
  const n=parseFloat((document.getElementById("rzTbPort")||{}).value)||1;
  const faktor=(fK*n)/P0;   // Rezept-Zutatenmengen gelten für P0 Portionen
  const {data,error}=await client.rpc("cb_tb_rezept",{p_mahlzeit:meal,p_rezept:r.id,p_datum:tbToday(),p_faktor:faktor});
  if(error){ if(msg){msg.style.color="var(--k-dc2626)";msg.textContent="Fehler: "+error.message;} return; }
  if(msg){ msg.style.color="var(--k-16a34a)"; msg.textContent="✓ "+(data||("Zutaten in "+meal+" übernommen")); }
  loadRezeptBudget();
}
